
'use strict';
let releasePrepared=null,releaseName='Neue Lerngruppe';
let token=sessionStorage.getItem('nordlicht-token'), record=null, page='overview', chosen='web', chosenUser='lea', appResult=null,requestResult=null, appUser='u11', appSource='hq', appMfa=true, editingOrder='NL-1001', focusTicket=null, progressOverview=null, progressDetail=null, bundleComparison=null, progressLoading=false, progressError='', busy=false, feedback='',dirty=false,recoveryDraft=null,metricSource='all';
const $=s=>document.querySelector(s), e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const eur=x=>Number(x).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})+' Lern-Euro';
const cmd=(label,action,parameters={},cls='')=>`<button type="button" class="${cls}" data-cmd="${e(JSON.stringify({action,parameters}))}">${e(label)}</button>`;
const table=(headers,rows)=>`<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const options=(values,selected)=>values.map(x=>{let [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${String(v)===String(selected)?'selected':''}>${e(l)}</option>`}).join('');
const input=(label,name,value='',type='text',attrs='')=>`<label>${e(label)}<input name="${e(name)}" type="${type}" value="${e(value)}" ${attrs}></label>`;
const select=(label,name,values,selected)=>`<label>${e(label)}<select name="${e(name)}">${options(values,selected)}</select></label>`;
const field=(label,name,value='')=>`<label class="wide">${e(label)}<textarea name="${e(name)}">${e(value)}</textarea></label>`;
const form=(id,body,button='Änderung speichern')=>`<form class="form" data-form="${id}">${body}<div class="wide"><button class="primary">${e(button)}</button></div></form>`;
const status=ok=>`<span class="pill ${ok?'good':'bad'}">${ok?'Erlaubt / bereit':'Verweigert / prüfen'}</span>`;
const card=(title,body)=>`<section class="card"><h2>${e(title)}</h2>${body}</section>`;
function toast(text,error=false){let t=$('#toast');t.textContent=text;t.className=error?'error':'';t.hidden=false;setTimeout(()=>t.hidden=true,6000)}
async function api(path,data){let response=await fetch(path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(data?{body:JSON.stringify(data)}:{})});let result=await response.json();if(!response.ok){if(response.status===409){if(dirty)result.error=(result.error||'Der Serverstand wurde inzwischen geändert.')+' Deine Formulareingaben bleiben erhalten. Sichere benötigten Text vor dem Neuladen; Neu laden fragt vor dem Verwerfen nach.';else await load();}const error=new Error(result.error||'Anfrage fehlgeschlagen');error.status=response.status;throw error;}return result;}
async function load(){bundleComparison=null;releasePrepared=null;record=await api('/api/state'+(record?'?instance='+encodeURIComponent(record.id):''));appResult=null,requestResult=null;feedback='';recoveryDraft=null;render();}
async function action(name,parameters={},expected=null,acceptDrafts=false){if(busy)return;if(dirty&&!acceptDrafts){toast('Formulareingaben zuerst mit ihrem Formular speichern. Neu laden oder Ansichtswechsel fragt vor dem Verwerfen nach.',true);return;}if(name==='progress_overview'){await refreshProgress(true);return;}if(['progress_detail','progress_export','summary','export','bundle_export','bundle_import','bundle_compare','import','compare','release_preview','release_instance','example_preview'].includes(name)&&dirty){toast('Formulareingaben zuerst speichern, damit sie erhalten bleiben.',true);return;}busy=true;const surface=$('#app');if(surface)surface.inert=true;try{if(expected&&(record.id!==expected.id||record.revision!==expected.revision))throw new Error('Zielinstanz inzwischen geändert. Datei erneut wählen.');const before={id:record.id,revision:record.revision};const out=await api(['bundle_import','bundle_compare','release_preview','release_instance'].includes(name)?'/api/bundle':['import','compare'].includes(name)?'/api/save':'/api/action',{instance:before.id,revision:before.revision,action:name,parameters});record=out.record;if(before.id!==record.id||before.revision!==record.revision){bundleComparison=null;releasePrepared=null;recoveryDraft=null;}dirty=false;if(name==='erase_progress')resetSessionView();if(name==='delete_instance'){progressOverview=null;progressDetail=null;}if(['application_open','order_create','order_update'].includes(name))appResult=out.result;else if(!['export','summary','notes','reply','hint'].includes(name))appResult=null,requestResult=null;feedback='';
if(['request_open','request_create','request_update'].includes(name))requestResult=out.result;
if(name==='release_instance'){releasePrepared=null;progressOverview=null;feedback=renderResult(out.result);}
else if(name==='bundle_export'){download(out.result,'Gesamtspielstand',false);feedback='';}
else if(name==='bundle_compare'){bundleComparison=out.result;feedback='';}
else if(name==='summary'||name==='progress_export'){downloadProgress(out.result,parameters.output||'html');feedback='';}
else if(name==='progress_detail'){progressDetail=out.result;feedback='';}
else if(name==='export'){download(out.result,name==='export'?'Spielstand':'Zusammenfassung');feedback='';}
else if(name==='restore_preview'){recoveryDraft={area:out.result.area,...out.result.parameters};feedback=renderResult(out.result);}
else if(out.result!==null&&out.result!==undefined){feedback=typeof out.result==='string'?`<div class="notice">${e(out.result)}</div>`:renderResult(out.result)}
else feedback='';render();toast(['progress_detail','progress_export','summary','export','instances','compare','example','bundle_export','bundle_compare','restore_preview','release_preview','example_preview'].includes(name)?'Leseansicht erstellt · Stand '+record.revision:'Gespeichert · Stand '+record.revision);return out.result;
}catch(err){toast(err.message,true)}finally{busy=false;if(surface)surface.inert=false}}
function download(data,name,appendTask=true){let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download=`Nordlicht-${name}${appendTask?'-'+record.state.task:''}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderResult(r){if(r.kind==='management')return managementResult(r);if(r.kind==='example_preview')return examplePreviewHtml(r);if(r.kind==='release_preview')return card('Vorbereitete Datei prüfen · '+r.name,`<p>Nur gelesen; noch keine Instanz und kein Teilnehmercode angelegt. ${r.source_format==='nordlicht-save/v1'?'Einzelne Übung':'Gesamter Übungsbestand'}. Vorhandene Pseudonyme, Notizen, Abgaben und Historien werden beim Bereitstellen mitkopiert. Prüfe, ob sie in einen Ausgangszustand gehören. ${r.legacy?'Älteres Format: bei Bereitstellung wird die ursprüngliche Datei gesichert.':'Aktuelles Speicherformat.'}</p>${progressDetailHtml(r.report)}<button data-release-create>Als neue getrennte Lerninstanz bereitstellen</button><p class="muted">Bestehende Instanzen bleiben erhalten. Für jede unabhängige Person erneut bereitstellen; gemeinsam verwendeter Code führt ausdrücklich in dieselbe Gruppeninstanz.</p>`);if(r.kind==='instance_release')return card('Neue Lerninstanz bereitgestellt',`<p><strong>${e(r.name)}</strong> · ${e(r.instance)}<br>${r.exercises} Übungsstände · aktive Übung ${e(r.active_task)}. Bisherige Instanzen bleiben erhalten.</p><p>Teilnehmercode: <code>${e(r.code)}</code></p><p>Ein eigener Code gehört zu dieser neuen Instanz. Wer denselben Code verwendet, arbeitet gemeinsam an genau dieser Firma. Für unabhängige Arbeiten erneut getrennt bereitstellen. Code lokal weitergeben; er wird hier nicht automatisch versendet.</p><button data-instance="${e(r.instance)}">Neue Instanz als Trainer öffnen</button>`);if(r.kind==='save_comparison')return card('Einzelvergleich · Momentaufnahme Revision '+e(r.current.revision),`<p>Links: aktive Übung der gewählten Instanz. Rechts: eingelesene Datei. Es wurden keine Übungen überschrieben oder Prüfungen gespeichert. ${r.current.active_task===r.incoming.active_task?'Gleiche Aufgabenkennung.':'Unterschiedliche Aufgaben: Die Prüfkriterien sind nicht unmittelbar gleichwertig.'}</p><div class="grid two">${progressDetailHtml(r.current)}${progressDetailHtml(r.incoming)}</div>`);if(r.kind==='container_config')return card('Container-Konfiguration',`<p>${e(r.message)}</p>`);if(r.kind==='availability_event')return card('Lernzonenausfall',`<p>${e(r.message)}</p>`);if(r.kind==='trainer_fault')return card('Trainerstörung',`<p>${e(r.message)}</p><p class="muted">Der tatsächliche Zustand und frische Funktionsprüfungen entscheiden über die Aufgabe.</p>`);if(r.kind==='restore_preview')return restorePreviewHtml(r);if(r.kind==='local_file')return card('Lokales Datei-Benutzerergebnis',renderResult(r.authorization)+(r.authorization.allowed?'<pre class="code">'+e(r.document.content)+'</pre>':''));if(r.kind==='local_orders')return card('Lokale Anwendung als Benutzer',renderResult(r.authorization)+(r.authorization.allowed?table(['Kennung','Kunde','Betreff','Status'],r.orders.map(x=>[e(x.id),e(x.customer),e(x.subject),e(x.status)])):''));if(r.authorization)return renderResult(r.authorization);if(r.checks)return card(r.passed?'Zustandsprüfung bestanden':'Noch offene Prüfpunkte',checks(r.checks)+`<p>${e(r.explanation)}</p>`);if(r.path)return card('Verbindungstest',status(r.allowed)+`<ol>${r.path.map(p=>`<li>${e(p)}</li>`).join('')}</ol>`);if(r.network)return card('Effektiver Benutzerzugriff',status(r.allowed)+`<p>${e(r.authentication)}</p><p>${e(r.reason)}</p><details><summary>Gepruefter Netzpfad</summary><ol>${r.network.path.map(x=>`<li>${e(x)}</li>`).join('')}</ol></details>`+table(['Identität / Gruppe','Rolle','Geltungsbereich'],r.grants.map(g=>[e(g.principal),e(g.role),e(g.scope)])));return card('Ergebnis',`<pre class="code">${e(JSON.stringify(r,null,2))}</pre>`)}
function checks(rows){return `<ul class="checks">${rows.map(c=>`<li><span class="check ${c.passed?'':'fail'}">${c.passed?'✓':'○'}</span>${e(c.label)}</li>`).join('')}</ul>`}
function resetSessionView(){releaseName='Neue Lerngruppe';recoveryDraft=null;metricSource='all';page='overview';feedback='';focusTicket=null;chosen='web';chosenUser='lea';appUser='u11';appSource='hq';appMfa=true;editingOrder='NL-1001';appResult=null,requestResult=null;feedback='';progressOverview=null;progressDetail=null;bundleComparison=null;releasePrepared=null;progressError='';dirty=false;}
function loginScreen(){ $('#app').innerHTML=`<main class="login"><div class="brand"><i class="logo"></i>NORDLICHT<span>Cloud Campus · lokal & offline</span></div>${card('Dein Einstieg ins IT-Team',`<p>Arbeite in einer fiktiven Firma mit 60 Beschäftigten. Keine Azure-Zugänge, keine echten Kennwörter, keine Cloud-Kosten.</p><form id="login">${input('Sitzungscode aus dem Startfenster oder vom Trainer','code')}${input('Anzeigename / Pseudonym','name','Lernende Person')}<button class="primary">Lernumgebung öffnen</button></form><p class="statusline">Didaktische Simulation mit vereinfachtem Funktionsumfang.</p>`)}</main>`;$('#login').onsubmit=async ev=>{ev.preventDefault();let data=Object.fromEntries(new FormData(ev.target));try{let r=await api('/api/login',data);token=r.token;sessionStorage.setItem('nordlicht-token',token);record=null;resetSessionView();await load();if(record.state.name!==data.name)await action('notes',{name:data.name,text:record.state.notes})}catch(err){toast(err.message,true)}};}
const NAV=[['overview','◈','Firmenübersicht'],['organization','▥','Organisation'],['tickets','▣','Posteingang'],['local','⌂','Lokale Infrastruktur'],['requests','⇄','IaaS / PaaS / SaaS'],['orders','▧','Auftragsanwendung'],['resources','▦','Alle Ressourcen'],['availability','◉','Verfügbarkeit'],['network','⌘','Virtual Network'],['identity','♙','Microsoft Entra ID'],['storage','▤','Storage Accounts'],['backup','↶','Backup Center'],['monitor','◷','Azure Monitor'],['costs','€','Cost Management'],['cleanup','⌫','Datenbereinigung'],['policy','◇','Policy & Datenschutz'],['migration','⇢','Migration Center'],['notes','✎','Arbeitsnotiz'],['trainer','⚑','Trainerbereich']];
const PAGE_GUIDES={"overview":["Firmenübersicht; keine echte Azure-Dienstübersicht","Die Übersicht zeigt getrennte Prüfkontexte. MFA ist ein zusätzlicher simulierter Anmeldenachweis. VPN verbindet Standorte; NSG sind Regeln für Netzwerkverbindungen. CPU bezeichnet die modellierte Rechenlast. Grün bei einem Dienst beweist nicht alle Benutzerrechte.",[["Referenzzugriff","Momentaufnahme für genau den angezeigten Benutzer und Ort, kein gespeicherter Diagnoseversuch."],["Ist / Prognose","Bisherige Lernkosten gegenüber einer Hochrechnung auf einen Lernmonat."],["Instanz","Eine getrennte Firmenumgebung oder ausdrücklich gemeinsame Gruppenfirma."]]],"organization":["Azure Resource Manager; Identitätskontext aus Microsoft Entra ID","Ein Tenant ist das Verzeichnis für Identitäten. Eine Subscription ist das Abonnement für Ressourcen, Rollen und Lernkosten. Ressourcengruppen bündeln Ressourcen; eine Ressource ist ein einzelner Dienst. Die Zuordnung unten stammt aus deiner aktiven Firmenumgebung.",[["Ressourcengruppe","Verwaltungsgruppe zusammengehöriger Ressourcen, keine Benutzergruppe."],["Tag","Zusatzangabe wie Abteilung oder verantwortliche Stelle; erteilt kein Zugriffsrecht."],["Gruppenregion","Im echten Azure der Metadatenstandort der Ressourcengruppe, nicht automatisch der Standort jeder Ressource."]]],"tickets":["Firmeninterner Arbeitsauftrag; kein echter Azure-Dienst","Ein Ticket ist eine Anfrage aus der Firma. Lies Bedarf und Schutzbedingungen, untersuche den Zustand, ändere gezielt und teste erlaubte sowie unerlaubte Zugriffe. Eine Diagnose ist ein gespeicherter Prüfversuch. Eine Rückmeldung erklärt deine Arbeit; sie ersetzt keine Zustandsprüfung.",[["Prüfkriterium","Beobachtbare Bedingung im tatsächlichen Modellzustand."],["Veralteter Nachweis","Seit dem Versuch wurde etwas geändert; prüfe erneut."],["Hilfestufen","Denkanstoß, Diagnosehinweis und konkrete Hilfe können einzeln abgerufen werden."]]],"local":["On-Premises; bewusst getrennt von Microsoft Entra ID","On-Premises bedeutet Betrieb am eigenen Standort. AD ist hier ein lokaler Verzeichnisdienst, LAN das lokale Netzwerk und SQL der strukturierte Auftragsbestand. Lokale Konten und Freigaben sind von Cloud-Identitäten und Cloud-Rollen getrennt.",[["Freigabe","Ein über das Netz bereitgestellter Dateiordner mit eigenen Lese-/Schreibrechten."],["Dienstkonto","Eine simulierte Identität für ein Programm statt eines Menschen."],["VPN","Modellierte Standortverbindung; lokaler LAN-Zugriff benötigt sie nicht."]]],"requests":["Azure Virtual Machines / App Service; SaaS als externer Anbieterdienst","IaaS ist eine selbst betreute virtuelle Maschine. PaaS ist eine verwaltete Anwendungsplattform. SaaS ist eine fertige Anwendung beim Anbieter. Vergleiche, welche Betriebsaufgaben bei der Firma bleiben. Die Kundenanfragen sind eine eigene Anwendung, getrennt von Aufträgen.",[["Laufzeit","Der ausgewählte Dienst, auf dem ein Anwendungsprofil im Modell arbeitet."],["Lizenz","Hier ein fiktiver Preis pro berechtigtem SaaS-Benutzer."],["Anbieterbestand","Die SaaS-Anfragedaten liegen logisch getrennt; Umschalten kopiert sie nicht."]]],"orders":["Unternehmensanwendung auf VM oder App Service; keine fertige Azure-App","Ein Auftrag ist ein tatsächlich gespeicherter Geschäftsvorgang mit verknüpftem Beleg. Anmeldung, Netzwerkzugang und Datenberechtigung sind verschiedene Prüfungen. Die Dienstidentität ist das Konto der Anwendung für ihre Datenzugriffe. MFA bleibt ein simulierter Zusatznachweis.",[["Version","Fortlaufender Datenstand; eine alte Version darf keine neuere Änderung überschreiben."],["Anhang","Der verknüpfte Beleg benötigt zusätzlich Datei- und Dienstrechte."],["Auftragsrolle","Erlaubt Lesen oder Bearbeiten von Geschäftsdaten, nicht automatisch Ressourcenverwaltung."]]],"resources":["Azure Resource Manager; Virtual Machines, App Service und weitere Lernprofile","Eine Ressource ist ein einzelner verwalteter Dienst. Größe, Zustand und weitere wirksame Felder hängen vom Diensttyp ab. Tags sind Zusatzangaben für Organisation und Lernkosten. Eine private IP ist eine interne Adresse; eine öffentliche Lern-IP schafft allein noch keine Freigabe.",[["Image","Hier die unterstützte Paketversion einer Lernanwendung, kein echter Download."],["Löschschutz","Verhindert bestimmte Ressourcenlöschungen, nicht Stoppen oder Datenänderungen."],["Compute-Zuordnung","VM-Rechenkapazität; Herunterfahren und Freigeben haben unterschiedliche Lernkosten."]]],"availability":["Vereinfachte Verfügbarkeitszonen und Storage-Redundanz","Eine Verfügbarkeitszone ist ein getrennter Ausfallbereich innerhalb einer Region. Ein Replikat ist eine zusätzliche Laufzeitinstanz. Mehrere verteilte Instanzen können einen Zonenausfall überstehen; eine einzelne bleibt eine einzelne. Redundanz ersetzt keinen früheren Datenstand.",[["ZRS","Der logische Speicher bleibt bei einem einzelnen Lernzonenausfall erreichbar; keine echte Datenkopie."],["LRS / GRS","Im Modell primärer Standort in Zone1, keine automatische Regionsumschaltung."],["Restkapazität","Die tatsächlich noch verfügbaren Instanzen, nicht nur die bestellte Anzahl."]]],"network":["Azure Virtual Network und Network Security Groups; vereinfachtes VPN","Ein Virtual Network (VNet) ist ein privates Cloud-Netz, ein Subnetz ein Teil davon. DNS übersetzt Namen in Ziele. Eine NSG ist ein Regelsatz für Verbindungen; kleinere Prioritätszahlen werden zuerst geprüft. VPN verbindet den Firmenstandort mit dem Cloud-Netz.",[["CIDR","Schreibweise für einen Adressbereich, zum Beispiel 10.20.1.0/24."],["Port / Protokoll","Kennzeichnen den angesprochenen Dienst und die Verbindungsart, hier etwa TCP443."],["Inbound / Outbound","Eingehende beziehungsweise ausgehende Verbindung."],["NIC","Die logische Netzwerkschnittstelle mit Subnetz und Adresse."]]],"identity":["Microsoft Entra ID und Azure-Rollen; zwei getrennte Rechtesysteme","Entra ID ist das Cloud-Verzeichnis für Benutzer und Gruppen, kein lokales Active Directory. MFA ist ein zusätzlicher simulierter Anmeldenachweis. Azure-RBAC bezeichnet Rollen mit einem Geltungsbereich. Entra-Verzeichnisrollen, Ressourcenverwaltung und Datenrechte sind getrennt.",[["Reader / Contributor","Ressourcen ansehen / verwalten; Contributor darf allein keine Rollen zuweisen."],["User Access Administrator","Verwaltet Azure-Rollenzuweisungen im erlaubten Bereich."],["Vererbung","Eine Rolle aus Subscription oder Ressourcengruppe kann auch an einer Ressource wirken."],["Effektive Rechte","Alle noch wirksamen direkten und gruppenbasierten Zugriffswege zusammen."]]],"storage":["Azure Storage Accounts, Blob / Files und VM-Disk als getrennte Lernarten","Ein Storage Account bündelt Speicher. Blob ist eine Objekt-/Dateiablage, ein Blob-Container ein Teil davon. Files ist eine Netzwerkdateifreigabe, eine Disk ein VM-Datenträger. Anmeldung und Datenrechte bleiben vom Netzwerkzugang getrennt; eine Version ist ein früherer Dateiinhalt.",[["Hot / Cool","Speicherklassen mit unterschiedlichen fiktiven Lernpreisen."],["Öffentlich / anonym","Öffentliche Adresse und Zugriff ohne Identität sind verschiedene Einstellungen."],["SMB","Das vereinfachte Dateifreigabeprotokoll für Files, hier TCP445."],["Redundanz","Logische Ausfallsicherheit, kein Ersatz für die Wiederherstellung gelöschter Inhalte."]]],"backup":["Azure Backup als vereinfachter Lernbereich; lokale Sicherung separat","Ein Sicherungsplan ist eine Vorgabe, noch kein vorhandener Wiederherstellungspunkt. Ein Punkt enthält einen früheren Datenstand. RPO ist der tolerierte Verlustzeitraum, RTO die tolerierte Zeit bis zur Wiederherstellung. Vergleiche Soll und tatsächliche Ereignisse; stelle zunächst eine Kopie her.",[["Aufbewahrung","Wie lange Modellpunkte verfügbar bleiben; alte Exporte sind davon unabhängig."],["In-place","Bewusste Wiederherstellung am bisherigen Ort statt einer zusätzlichen Kopie."],["Rückfallpunkt","Gesicherter Stand vor einem Eingriff, kein Beweis einer erfolgreichen Wiederherstellung."]]],"monitor":["Azure Monitor; deterministische Metriken und Ereignisse","Eine Metrik ist ein Zahlenwert wie CPU-Rechenlast, RAM-Speicherbelegung oder Antwortzeit. Ein Log ist ein Ereignisprotokoll. Ein Alarm braucht Ziel, Schwelle und Auswertungsdauer. Werte entstehen aus dem tatsächlichen Modellzustand; neue Zeitpunkte nur durch bewusstes Vorspulen.",[["Fehlerrate","Anteil modellierter Dienstfehler, keine zufällige Kurve."],["ms","Millisekunden; hier ein vereinfachter Antwortzeitwert."],["Schwelle / Zeitraum","Ab welchem Wert und wie lange eine Regel erfüllt sein muss."]]],"costs":["Microsoft Cost Management; ausschließlich fiktive Lernpreise","Ist-Kosten sind bereits aufgelaufene Lernkosten. Eine Prognose rechnet aktuelle Einstellungen auf einen Lernmonat hoch. Ein Budget ist eine Vergleichsgrenze; eine Warnung schaltet keine Ressource ab. Prüfe Einheit und Rechenweg, bevor du eine Einstellung änderst.",[["EUR/h / GB","Lernpreis pro Stunde beziehungsweise Speichermenge; keine echte Azure-Rechnung."],["Tag","Abteilung und Verantwortung ordnen Lernkosten zu, erteilen aber keine Rechte."],["Reservierte Lernkosten","Einige Dienste bleiben im Modell auch gestoppt kostenpflichtig; typbezogene Hinweise beachten."]]],"cleanup":["Firmen-Datenminimierung; keine automatische Azure-Compliance","Datenminimierung bedeutet, nicht mehr benötigte Inhalte gezielt zu entfernen. Eine Frist gibt eine fiktive Aufbewahrungsdauer vor; eine Löschsperre kann die Bereinigung verhindern. Bekannte Kopien werden über ihre Herkunft verbunden, nicht allein über gleichen Text.",[["Tombstone","Ein verbleibender neutraler Kennungsdatensatz nach entfernter Nutzlast."],["Nutzdaten","Hier Dateiinhalt und geschäftliche Auftragsfelder statt notwendiger Steuerinformationen."],["Compliance","Erfüllung verbindlicher Vorgaben; der Simulator erteilt keinen rechtlichen Nachweis."]]],"policy":["Azure Policy als vereinfachte Regelprüfung; Datenschutz separat","Eine Policy ist eine Regel für zulässige Ressourceneinstellungen, etwa Regionen, Tags und öffentliche Zugänge. Sie ist keine Benutzerrolle. Eine Datenklasse beschreibt Schutzbedarf. Eine erlaubte Region ist allein kein Nachweis für Datenschutzkonformität.",[["Governance","Vorgegebene Regeln und Verantwortung für den Betrieb."],["Vertraulich","Fiktive Daten mit begrenztem vorgesehenem Leserkreis."],["Besonders schutzbedürftig","Erhöhter Schutzbedarf; hier ausschließlich fiktive Beispiele."]]],"migration":["Azure Migrate; hier Lernbereich „Migration Center“","Migration bedeutet einen geplanten Umzug mit Datenabgleich, Test, Umschaltung und Nachkontrolle. Rehost übernimmt eine Laufzeit auf eine VM, Replatform wechselt auf eine verwaltete Plattform. Rollback ist der Rückfall auf einen gesicherten vorherigen Stand. Eine DNS-Änderung allein kopiert keine Daten.",[["Inventar / Eignung","Vorhandene Systeme und ihre Abhängigkeiten gegenüber einem möglichen Ziel prüfen."],["Cutover","Bewusste Umschaltung nach bestandenem Zieltest."],["Abgleich","Prüfen, ob kopierte Daten zum aktuellen Quellstand passen."]]],"notes":["Persönliche Arbeitsnotiz und lokale Spielstanddateien","Halte Beobachtung, Vermutung, Änderung und Nachweis getrennt fest. Ein Export ist eine heruntergeladene Spielstanddatei, ein Import lädt sie bewusst zurück. JSON ist hier nur ein Datenformat. OneDrive verteilt Dateien und ist kein Anwendungsserver.",[["Gesamtspielstand","Alle bereits geöffneten Übungen der ausgewählten Firmeninstanz."],["Zusammenfassung","Ein Bericht für die Besprechung, kein vollständiges Backup."],["Pseudonym","Frei gewählter Anzeigename; keine echten personenbezogenen Inhalte erforderlich."]]],"trainer":["Lehrkraftsteuerung; keine echte Azure-Administratoroberfläche","Eine Instanz ist eine getrennte Firma oder eine bewusst gemeinsame Gruppenfirma. Die Revision ist ihre Änderungsnummer und verhindert unbemerkte Überschreibungen. Aufgaben, Fehler und Simulationszeit steuert die Lehrkraft. Der Server prüft diese Berechtigungen, nicht nur die Sichtbarkeit eines Knopfs.",[["Vergleich","Lesende Gegenüberstellung; ersetzt keinen fremden Teilnehmerstand."],["Zurücksetzen","Betrifft nur die ausgewählte Übung/Instanz; vorher Auswirkungen prüfen."],["Lernnachweis","Besprechbarer Zustand und Tests; lokale Dateien sind keine manipulationssichere Prüfung."]]]};
function pageHelp(id){const guide=PAGE_GUIDES[id];return guide?`<section class="notice" aria-label="Orientierung und Begriffe"><p><strong>Orientierung · ${e(guide[0])}</strong><br>${e(guide[1])}</p><details><summary>Weitere Begriffe für diese Seite</summary>${table(['Begriff','Bedeutung im Lernmodell'],guide[2].map(([term,meaning])=>[e(term),e(meaning)]))}</details></section>`:'';}
function organizationPage(){const s=record.state;return `<div class="grid two">${card('Identitätskontext · Entra-Tenant',`<p><strong>${e(s.tenant)}</strong></p><p>Verzeichnis für ${Object.keys(s.users).length} simulierte Identitäten einschließlich Gast- und IT-Lernrolle sowie ${Object.keys(s.groups).length} Gruppen. Diese Zahl ist keine Beschäftigtenzählung. Entra-Verzeichnisrollen betreffen das Verzeichnis; sie sind keine Azure-Ressourcenrollen.</p><button data-page="identity">Benutzer, Gruppen und wirksame Rechte prüfen</button>`)}${card('Ressourcenkontext · Subscription',`<p><strong>${e(s.subscription)}</strong></p><p>Dieses Lernabonnement nutzt den oben gezeigten Tenant als Identitätskontext. Es enthält ${Object.keys(s.resource_groups).length} Ressourcengruppen und ${Object.keys(s.resources).length} Ressourcen. Ein Tenant kann im echten Azure mehrere Subscriptions bedienen; hier ist pro Übung genau ein Kontext modelliert. Keine echten Konten, Abonnements oder Azure-Verbindungen.</p><p>Verwaltungshierarchie: Subscription → Ressourcengruppe → Ressource. Management Groups und Tenant-/Subscription-Wechsel sind nicht modelliert.</p><button data-page="costs">Lernkosten und Budget prüfen</button>`)}</div><br>`+card('Ressourcengruppen und tatsächliche Zuordnung',`<p>Eine Ressourcengruppe bündelt Ressourcen für Verwaltung und Rollenbereiche; sie ist keine Entra-Benutzergruppe. Ihre gespeicherte Region beschreibt im Lernmodell den Metadatenstandort. Die Region jedes Dienstes steht separat daneben; sie wird nicht automatisch aus der Gruppe übernommen. Gruppen-Tags werden nicht stillschweigend auf Ressourcen vererbt.</p><button data-page="resources">Ressourcen konfigurieren oder Ressourcengruppe anlegen</button>`)+Object.entries(s.resource_groups).map(([id,g])=>{const rows=Object.entries(s.resources).filter(([key,r])=>r.group===id);return card(id,`<p>Gruppenregion: <strong>${e(g.region)}</strong> · Abteilung: ${e(g.department)} · Verantwortlich: ${e(g.owner)}<br>${rows.length} zugeordnete Ressourcen · ${s.roles.filter(r=>r.scope===id).length} direkte Azure-Lernrollenzuweisungen an dieser Gruppe.</p>`+table(['Ressource / Dienst','Ressourcenregion','Ressourcen-Tags',''],rows.map(([key,r])=>[e(key)+' · '+e(r.name)+'<br>'+e(r.kind),e(r.region),e(r.department)+' / '+e(r.owner),`<button data-resource="${e(key)}">Ressource untersuchen</button>`]))+(rows.length?'':'<p>Diese Gruppe enthält derzeit keine Ressourcen.</p>'));}).join('')+card('Rollen und Kosten gemeinsam verstehen',`<p>Eine Azure-Rolle an der Subscription oder Ressourcengruppe kann untergeordnete Ressourcen erfassen. Weitere direkte oder gruppenbasierte Wege können trotz Entfernung einer einzelnen Rolle bestehen bleiben. Ressourcenverwaltung erteilt keine automatische Datenfreigabe; Entra-Verzeichnisrollen bleiben getrennt.</p><p>Abteilungs- und Verantwortungs-Tags ordnen die Firma und Lernkosten; sie sind keine Rechtezuweisung. Standortzahl der Firma: ${Object.values(s.locations).reduce((sum,count)=>sum+count,0)} fiktive Beschäftigte. Die Verzeichniszählung oben umfasst zusätzliche Lernidentitäten.</p><button data-page="identity">Als Benutzer testen</button> <button data-page="network">Verbindungsweg getrennt prüfen</button>`);}
function render(){if(!record)return;const s=record.state;if(!s.users[chosenUser])chosenUser='lea';if(!s.resources[chosen])chosen='web';if(!s.users[appUser]){appUser=s.users.u11?'u11':'lea';appResult=null,requestResult=null;feedback='';}$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><i class="logo"></i>NORDLICHT<span>Cloud Campus</span></div><div class="nav-label">Dein Unternehmen</div><nav>${NAV.filter(n=>n[0]!=='trainer'||record.role==='trainer').map(([id,icon,label])=>`<button class="nav ${page===id?'active':''}" data-page="${id}" title="${e(PAGE_GUIDES[id]?.[0]||label)}"><i>${icon}</i>${label}</button>`).join('')}</nav><div class="sidefoot">60 fiktive Beschäftigte<br>Hauptstandort · Außenstelle · Homeoffice<br><br>Didaktische Simulation.<br>Keine Verbindung zu Azure.</div></aside><div><header class="top"><div><strong>${e(s.company)}</strong> <small>/ ${e(record.name)}</small></div><div><span class="pill">${e(record.role==='trainer'?'Solo / Trainer':'Teilnehmer')}</span> <small>● Minute ${s.minute}</small></div></header><main class="page"><div class="heading"><div><div class="eyebrow">Nordlicht Lernportal</div><h1>${e(NAV.find(n=>n[0]===page)?.[2]||'Lernportal')}</h1><small>Verzeichnis (Tenant): ${e(s.tenant)} · Abonnement (Subscription): ${e(s.subscription)}</small></div><button data-reload>↻ Aktualisieren</button></div>${pageHelp(page)}<div id="result" aria-live="polite">${feedback}</div>${content()}<div class="statusline"><span class="statusdot"></span>Automatisch serverseitig gespeichert · Revision ${record.revision} · Zeit läuft ausschließlich durch Vorspulen. Lokale Stände sind keine manipulationssicheren Prüfungsnachweise.</div></main></div></div>`;bind();}
function overviewAccess(){const ref=record.state.computed.reference_application;return `<p>Referenz: Aufträge lesen als <strong>${e(ref.user)}</strong> am Hauptstandort, mit simuliertem MFA-Nachweis.</p>${status(ref.authorization.allowed)}<p>${e(ref.authorization.reason)}</p><details><summary>Aktuell geprüfter Verbindungs- und Abhängigkeitspfad</summary><ol>${ref.authorization.network.path.map(x=>`<li>${e(x)}</li>`).join('')}</ol></details><p class="muted">Momentaufnahme ohne neue gespeicherte Diagnose. Andere Benutzer, Schreibrechte und einzelne Anhänge separat prüfen.</p><button data-page="orders">Auftragsanwendung als Benutzer prüfen →</button>`;}
const TICKET_STATES={passed:'Aktuell bestanden',stale:'Ergebnis veraltet · erneut prüfen',ready:'Prüfkriterien erfüllt · noch abgeben',unsubmitted:'Noch nicht abgegeben',open:'Prüfung offen',invalid:'Gespeicherter Stand nicht auswertbar',not_started:'Noch nicht geöffnet'};
function companyTicketPanel(){const q=record.tickets;if(!q)return card('Aufträge dieser Instanz','<p>Auftragsübersicht nicht geladen. Bitte aktualisieren.</p>');const rowHtml=rows=>table(['Auftrag','Absender','Stand',''],rows.map(r=>[e(r.title)+(r.active?' <small>· aktive Übung</small>':''),e(r.sender),e(TICKET_STATES[r.status]||'Unbekannter Prüfstand')+(r.exercise_status==='paused'?'<br><strong>Durch Trainer pausiert</strong>':''),`<button data-ticket-open="${e(r.id)}">Nachricht lesen</button>`]));const open=q.rows.filter(r=>r.saved&&r.status!=='passed');return card('Aufträge dieser Instanz',`<p>${q.totals.passed} aktuell bestanden · ${q.totals.needs_attention} gespeicherte Aufträge offen / erneut zu prüfen · ${q.totals.not_started} noch nicht geöffnet. Davon ${q.totals.paused} pausiert.</p>`+(open.length?rowHtml(open):'<p>Keine gespeicherten offenen Aufträge.</p>')+`<details><summary>Alle ${q.totals.total} Kursaufträge einschließlich noch nicht geöffneter Aufgaben</summary>${rowHtml(q.rows)}</details><p class="muted">Aktiver und gespeicherte Übungsstände werden getrennt neu geprüft. Eine alte Abschlussmarkierung allein zählt nicht. Noch nicht geöffnet bedeutet keine automatische Freigabe; der Trainer wählt die aktive Übung. Sandbox ist kein bewerteter Auftrag.</p>`);}
function companyServicePanel(){const s=record.state,p=s.onprem,ref=s.computed.reference_request;let local;
if(!p.enabled)local='<p>Lokaler Datenbereich in diesem älteren Stand noch nicht eingerichtet.</p>';
else {const moved=s.local_migration.active;local=`<p>${moved?'Übernommener lokaler Auftragsbestand · aktuelles Cloudziel '+e(s.local_migration.target):'Lokaler Auftragsbestand · AD-/SQL-/FILE-Pfad'} · Referenz u11 am Hauptstandort, Aufträge lesen.</p>${status(s.computed.local_application.allowed)}<p>${e(s.computed.local_application.reason)}</p>`+table(['Lokaler Dienst','TCP-Pfad vom Hauptstandort','Grund'],Object.entries(s.computed.local_tcp).map(([id,net])=>[e(id),status(net.allowed),e(net.path[net.path.length-1])]))+`<p class="muted">TCP-Erreichbarkeit ist kein Nachweis für AD-Anmeldung, Datei-/SQL-Rechte oder erfolgreiche Sicherung. Lokaler AD-Bereich und Entra bleiben getrennt.</p>`;const b=p.backup,last=b.jobs[b.jobs.length-1];local+=`<p>Lokaler Sicherungsplan: ${b.enabled?'aktiv':'inaktiv'} · ${b.points.length} vorhandene Modellpunkte. Letzter protokollierter Lauf: ${last?e(last.status)+' in Minute '+e(last.minute)+' · '+e(last.reason):'noch keiner'}.</p>`;}
local+='<button data-page="local">Lokale Dienste und übernommenen Bestand untersuchen</button>';const deployment=ref&&s.requests.deployments[ref.model];let request=deployment?`<p>Ausgewählt: <strong>${e(ref.model)}</strong> · ${e(deployment.resource)} · ${ref.model==='SaaS'?'externer Anbieterdienst und eigener Anbieterbestand':'Unternehmensdienst und Firmenbestand'}. Referenz u11 am Hauptstandort, Anfragen lesen, simulierter MFA-Nachweis.</p>${status(ref.authorization.allowed)}<p>${e(ref.authorization.reason)}</p>`:'<p>Keine Anfrage-Alternative ausgewählt. IaaS, PaaS und SaaS können im eigenen Bereich bereitgestellt und verglichen werden.</p>';
request+='<p class="muted">Nur der ausgewählte Dienst wird hier geprüft; ein Modellwechsel kopiert keine Daten. Weitere bereitgestellte Dienste können weiterhin Kosten verursachen. Diese Momentaufnahme erzeugt keine gespeicherte Anmeldung oder Diagnose.</p><button data-page="requests">Anfrageannahme und Alternativen prüfen</button>';return '<br><div class="grid two">'+card('Lokale Dienste und ihr Auftragsbestand',local)+card('Anfrageannahme · gewählte Alternative',request)+'</div>';}
function overviewPage(t){const s=record.state,m=s.computed.metrics.container,containerReady=m.available&&m.error_rate===0;const containerReason=!m.available?m.reason:m.error_rate>0?'Modellierte Kapazität überschritten: '+m.error_rate+' % Dienstfehler bei '+m.cpu+' % CPU.':'Laufzeit, Konfiguration und Abhängigkeiten im Modell bereit. Netzpfad und Benutzerrechte separat prüfen.';
return `<div class="hero"><div class="eyebrow" style="color:#8db4fa">Dein Arbeitsplatz · Unternehmens-IT</div><h2 style="font-size:27px;margin:9px 0">Du hältst die Firma arbeitsfähig.</h2><p>Untersuche Ressourcen, löse Anfragen aus den Abteilungen und prüfe, ob deine Änderung im Unternehmen funktioniert.</p><button data-page="tickets">Aktuellen Auftrag öffnen →</button> <small>${e(t.title)} · ${t.minutes} min</small></div><div class="grid">${card('Auftragsdienst · Referenzzugriff',overviewAccess()+`<hr><div class="stat">${metricDisplay(s.computed.active_metrics,'response_ms')} <small>ms</small></div><small>Antwortzeit des Laufzeitmodells, keine Messung dieses Benutzerzugriffs · ${e(s.computed.active_metrics.reason||'')}</small>`)}${card('Lernkosten',`<div class="stat">${eur(s.cost)}</div><small>Ist-Kosten seit Minute 0 · Prognose ${eur(s.computed.monthly)}/Monat</small>`)}${card('Dein Fortschritt',`<div class="stat">${record.tickets?record.tickets.totals.passed:'—'} <small>aktuell bestandene Kursaufträge</small></div><small>${s.diagnostics.length} Diagnosen · ${s.hints.length} Hilfen</small>`)}</div><br><div class="grid two">${card('Zusammenhängende Firmenumgebung',table(['Standort','Beschäftigte'],Object.entries(s.locations).map(([k,v])=>[e(k),v]))+`<p class="muted">Geschäftsführung, Vertrieb, Personal, Buchhaltung, Betrieb und IT.</p>`)}${card('Dienste & Abhängigkeiten',table(['Bereich / Prüfkontext','Zustand','Grund / nächster Schritt'],[['Aufträge lesen · u11 · Hauptstandort',status(s.computed.reference_application.authorization.allowed),e(s.computed.reference_application.authorization.reason)+'<br><button data-page="orders">Benutzerzugriff prüfen</button>'],['Versand-Container · Laufzeitmodell',status(containerReady),e(containerReason)+'<br><button data-resource="container">Container untersuchen</button>'],['Standort-VPN · Verbindungsschalter',status(s.network.vpn),(s.network.vpn?'VPN im Modell verbunden.':'VPN im Modell unterbrochen.')+' DNS, NSG, Dienst und Datenrechte sind weitere Prüfpunkte.<br><button data-page="network">Netzpfad diagnostizieren</button>']]))}</div>`+companyServicePanel()+'<br>'+companyTicketPanel();}
function content(){const s=record.state,t=record.catalog.find(t=>t.id===s.task),r=s.resources;switch(page){
case 'organization':return organizationPage();
case 'overview':return overviewPage(t);
case 'tickets':return `<div class="split"><div class="card"><h2>Aufträge</h2><div class="tickets">${record.catalog.map(x=>`<button class="ticket ${x.id===s.task?'selected':''}" data-ticket="${e(x.id)}"><strong>${e(x.id==='intro'?'Einstieg':x.id==='free'?'Sandbox':'Auftrag '+x.id)} · ${e(x.title)}</strong><small>${e(x.sender)} · ${x.minutes} min ${s.completed[x.id]?.passed?'· ✓':''}</small></button>`).join('')}</div></div><div>${ticket(focusTicket?record.catalog.find(x=>x.id===focusTicket):t)}</div></div>`;
case 'local':return localPage();
case 'requests':return requestPage();
case 'orders':return orderPage();
case 'resources':{let v=r[chosen]||r.web;return card('Ressourcen in der Subscription',table(['Anzeigename / Lernkennung','Dienst','Gruppe / Region','Betriebszustand (kein Funktionstest)',''],Object.entries(r).map(([k,v])=>[e(v.name)+'<br><small>'+e(k)+'</small>',e(v.kind),e(v.group)+'<br><small>'+e(v.region)+'</small>',e(resourceStatus(v.status)),`<button data-resource="${e(k)}">Öffnen</button>`])))+`<div class="grid two">${card(v.name,`<p class="notice">${v.kind==='SaaS'?'Externer SaaS-Dienst: Anbieter betreibt Anwendung, Laufzeit und Betriebssystem. Unternehmen verantwortet Konten, Daten und Freigaben.':v.kind==='VM'?'IaaS: Anbieter betreibt Hardware; Unternehmen verwaltet Betriebssystem, Anwendung und Zugriffe.':'Verwalteter Dienst: Betriebssystem durch Anbieter; Anwendung, Konfiguration, Daten und Zugriffe durch Unternehmen.'}</p>${resourceIdentityNotice(chosen)}${nicDnsHint(chosen)}${runtimeProfileNotice(chosen)}${resourceFaultNotice(chosen)}${availabilityResourceNotice(chosen)}${(v.kind==='Storage'?storageAccountForm(chosen,v):v.kind==='File Share'?fileShareForm(chosen,v):v.kind==='Container Apps'?containerAppForm(chosen,v):v.kind==='Database'?databaseForm(chosen,v):form('resource',input('Anzeigename im Lernportal','name',v.name)+select('Region','region',['germanywestcentral','westeurope','eastus'],v.region)+input('Abteilung (Tag)','department',v.department)+input('Verantwortliche Stelle (Tag)','owner',v.owner)+(v.kind==='SaaS'?'':select('Verteilung im Lernmodell','availability',[['single','Ein Standort (Zone1)'],['zones','Instanzen über Lernzonen1–3']],v.availability)+select('Größe / CPU / RAM','size',Object.entries(s.tariffs.sizes).map(([key,row])=>[key,key+' · '+row.cpu+' CPU / '+row.ram+' GB']),v.size)+(v.kind==='App Service'?'<p>Gespeichertes Plattformprofil: '+e(v.os)+' · nur Beschreibung; keine simulierte OS-Kompatibilitätsprüfung oder Plattformpflege durch Lernende.</p>':input('Betriebssystem (Inventar; keine echte Installation)','os',v.os))+(v.kind==='App Service'?'':input('Datenträger (GB)','disk_gb',v.disk_gb,'number','min="0" max="1024"'))+select('Subnetz / NIC-Zuordnung','subnet',Object.keys(s.network.subnets),v.subnet)+input('Private IP / Netzwerkkarte','ip',v.ip)+input('Öffentliche Lern-IP (leer = kein Internet-Endpunkt)','public_ip',v.public_ip)+input('Dienstport','port',v.port,'number','min="1" max="65535"')+(v.kind==='Storage'?select('Anonyme Blob-Freigabe','public',[['false','Identität erforderlich'],['true','Anonym lesen']],v.public):'')+select('Löschschutz','locked',[['false','Aus'],['true','Aktiv']],v.locked)+input('Image-Version','image',v.image)+input('Instanzen (Lern-Replikate)','instances',v.instances,'number','min="1" max="10"')+select('Konfiguration vollständig','configured',[['true','Ja'],['false','Nein']],v.configured))))}<div class="actions">${(['SaaS','File Share','Storage'].includes(v.kind)?[]:['App Service','Container Apps','Database'].includes(v.kind)?['start','restart','shutdown']:['start','restart','shutdown','deallocate']).map((x,i)=>cmd(['Starten','Neustarten',v.kind==='VM'?'OS herunterfahren':v.kind==='Database'?'Datenbank stoppen':'Anwendung stoppen','Zuordnung freigeben'][i],'power',{id:chosen,operation:x})).join('')}${cmd('Ressource löschen','delete_resource',{id:chosen},'danger')}</div><p class="muted">VM: Herunterfahren behält Compute-Kosten, Deallokieren beendet Compute bei weiter berechnetem Datenträger. App Service: Stoppen oder Neustarten der Anwendung hebt die Lern-Plankosten nicht auf. Jede App-Service-Ressource steht vereinfacht für eine App samt eigenem Plan; kein gemeinsam genutzter Plan. Ältere importierte deallocated-Stände bleiben offline, werden aber weiterhin als vorhandener Plan berechnet. Container Apps: Starten/Stoppen steuert die Lernlaufzeit, keine VM-Zuordnung. Stoppen behält im reservierten Lernkapazitätsmodell die Kosten; alte importierte deallocated-Werte werden unverändert erhalten. Löschschutz schützt nicht vor Stoppen oder Datenänderungen.</p>`)}${card('Organisation & neue Ressource',form('rg',input('Ressourcengruppe','id','rg-neuprojekt')+select('Region','region',['germanywestcentral','westeurope'],'germanywestcentral')+input('Abteilung','department','Vertrieb')+input('Verantwortlich','owner','Projektleitung'),'Ressourcengruppe anlegen')+`<hr>`+form('create',input('Eindeutige Ressourcen-ID','id','labvm')+input('Anzeigename im Lernportal','name','vm-labor')+select('Dienst','kind',['VM','App Service','Container Apps','Storage','File Share','SaaS'],'VM')+select('Ressourcengruppe','group',Object.keys(s.resource_groups),'rg-lab')+select('Region der neuen Ressource','region',s.policy.regions,s.policy.regions[0])+input('Abteilung (Ressourcen-Tag)','department','IT')+input('Verantwortlich (Ressourcen-Tag)','owner','IT-Leitung')+select('Zielsubnetz','subnet',Object.keys(s.network.subnets),s.resources.web.subnet)+input('Freie private IP','ip','10.20.1.60'),'Ressource anlegen')+`<p class="muted">Region und Tags gelten für die neue Ressource. Die Region einer Ressourcengruppe bestimmt deren Metadatenablage und erzwingt keine automatische Ressourcenregion. Die Lern-Policy prüft den gewählten Ressourcenstand vor dem Anlegen.</p>`+table(['Gruppe','Abteilung','Verantwortlich'],Object.entries(s.resource_groups).map(([k,v])=>[e(k),e(v.department),e(v.owner)])))}</div>`;}
case 'availability':return availabilityPage();
case 'network':return networkPanel()+card('Network Security Group (NSG)',`<p class="muted">NSG = Netzwerk-Sicherheitsgruppe. Niedrige Prioritätszahl zuerst; erster Treffer entscheidet. Danach gelten die vereinfachten Standardregeln AllowVnet/AllowInternetOutBound und DenyAllInBound.</p>`+table(['ID / Priorität','Richtung / Protokoll','Quelle','Ziel : Port','Aktion',''],s.network.rules.map(x=>[e(x.id)+' / '+x.priority,e(x.direction)+' / '+e(x.protocol),e(x.source),e(x.destination)+' : '+(x.port||'*'),e(x.action),cmd('Entfernen','rule_remove',{id:x.id})]))+form('rule',input('Regel-ID','id','web-allow')+input('Priorität (100–4096)','priority',300,'number')+select('Richtung','direction',['Inbound','Outbound'],'Inbound')+select('Protokoll','protocol',['TCP','UDP','*'],'TCP')+input('Quelle: IP/CIDR, * oder VirtualNetwork','source','10.10.0.0/16')+select('Ziel','destination',['*',...Object.keys(r)],'web')+input('Port (0 = alle)','port',443,'number')+select('Aktion','action',['Allow','Deny'],'Allow'),'Regel hinzufügen'));
case 'identity':return serviceIdentityCard()+`<div class="notice">Entra ID verwaltet Cloud-Identitäten. Klassisches AD DS betreibt hier lokal die Domäne; Entra-Verzeichnisrollen und Azure-Ressourcenrollen sind getrennt. Keine echten Kennwörter oder MFA-Codes eingeben.</div><div class="grid two">${card('Identitäten & Gruppen',form('user',select('Benutzer','id',Object.entries(s.users).map(([k,v])=>[k,v.name]),chosenUser)+select('Konto aktiv','active',[['true','Ja'],['false','Nein']],s.users[chosenUser].active)+select('MFA-Lernnachweis','mfa',[['true','Vorhanden'],['false','Fehlt']],s.users[chosenUser].mfa)+select('Verzeichnisrolle (keine Azure-Rolle)','directory_role',['User','User Administrator','Global Administrator'],s.users[chosenUser].directory_role)+select('Gast','guest',[['false','Nein'],['true','Ja']],s.users[chosenUser].guest)+input('Gastablauf (Simulationsminute)','expires',s.users[chosenUser].expires,'number'),'Benutzer ändern')+form('newuser',input('Neue Benutzerkennung','id','neu')+input('Fiktiver Anzeigename','name','Alex Beispiel')+input('Abteilung','department','Vertrieb'),'Benutzer anlegen')+form('membership',select('Gruppe','group',Object.keys(s.groups),'Vertrieb')+select('Benutzer','member',Object.keys(s.users),'lea')+select('Mitgliedschaft','add',[['true','Hinzufügen'],['false','Entfernen']],'true'),'Gruppenmitgliedschaft ändern')+table(['Gruppe','Mitglieder'],Object.entries(s.groups).map(([k,v])=>[e(k),e(v.join(', '))])))}${card('Rollenzuweisungen (Azure RBAC)',`<p class="muted">Reader: ansehen. Contributor: verwalten, keine Rollen zuweisen. User Access Administrator: Rollen zuweisen. Blob-Rollen: Daten lesen bzw. schreiben. Vererbung: Subscription → Ressourcengruppe → Ressource → Container/Dokument (didaktisch vereinfacht). Shared Keys und SAS sind nicht modelliert.</p>`+form('role',select('Identität / Gruppe','principal',[...Object.keys(s.users),...Object.keys(s.groups),...Object.keys(s.service_principals)],'lea')+select('Rolle','role',['Reader','Contributor','User Access Administrator','Blob Reader','Blob Contributor','File Reader','File Contributor','Disk Reader','Disk Contributor','Request Operator','Order Reader','Order Operator'],'Blob Reader')+select('Geltungsbereich','scope',['subscription',...Object.keys(s.resource_groups),...Object.keys(r),'sales','hr','requests',...Object.keys(s.documents)],'sales')+select('Änderung','operation',[['role_add','Zuweisen'],['role_remove','Entziehen']],'role_add'),'Zuweisung anwenden')+table(['Identität','Rolle','Scope',''],s.roles.map(x=>[e(x.principal),e(x.role),e(x.scope),cmd('Entziehen','role_remove',x)])))}</div>`+card('Als Benutzer testen',accessForm())+card('Verwaltungsrechte getrennt testen',managementForm())+card('Benutzerverzeichnis',table(['Kennung','Name / Abteilung','Aktiv / MFA / Gast','Entra-Verzeichnisrolle'],Object.entries(s.users).map(([k,u])=>[e(k),e(u.name)+'<br>'+e(u.department),`${u.active?'aktiv':'gesperrt'} / ${u.mfa?'MFA':'kein MFA'} / ${u.guest?'Gast bis '+u.expires:'intern'}`,e(u.directory_role)])));
case 'storage':return storagePlacementPanel()+dataGovernancePanel()+`<div class="notice">Storage Account: stnordlicht · Blob-Container: sales, hr, public · lokale Dateiablage: FILE-01 · VM-Blockdatenträger: Ressourcenansicht. Dokument-Scopes sind eine Lernvereinfachung; Azure Blob RBAC ist normalerweise mindestens am Container angesetzt.</div><div class="grid two">${card('Dokumentenablage',table(['Datei / Container','Datenklasse','Version / Zustand','Inhalt'],Object.entries(s.documents).map(([k,d])=>[e(k)+'<br><small>'+e(d.name)+' / '+e(d.container)+'</small>',e(d.class),d.version+' / '+(d.deleted?'gelöscht':'vorhanden'),e(d.deleted?'—':d.content)]))+form('file',select('Dokument','id',Object.keys(s.documents),'offer')+select('Aktion','operation',[['file_write','Inhalt ändern / neue Version'],['file_delete','Löschen'],['version_restore','Frühere Version wiederherstellen']],'file_write')+field('Neuer Inhalt (nur fiktive Daten)','content','Angebot A: überarbeiteter Lerninhalt.')+input('Versionsnummer bei Versionswiederherstellung','version',1,'number'),'Dateiaktion ausführen'))}${card('Speicherkonfiguration',storageAccountForm('storage',r.storage)+accessForm())}</div>`+card('Dateiversionen',table(['Dokument','Version','Zeitpunkt','Inhalt'],Object.entries(s.documents).flatMap(([k,d])=>d.versions.map(v=>[e(k),v.version,'Minute '+v.modified,e(v.content)]))));
case 'backup':{let b=s.backup;return `<div class="grid two">${card('Sicherungsplan',form('backup',input('Intervall (Minuten)','interval',b.interval,'number','min="1"')+input('Aufbewahrung (Minuten)','retention',b.retention,'number','min="1"')+select('Plan aktiv','enabled',[['true','Ja'],['false','Nein']],b.enabled))+`<div class="actions">${cmd('Jetzt sichern','backup_run')}</div><p class="muted">Ein Plan ist noch kein Wiederherstellungspunkt. Zeit bewusst vorspulen und das Sicherungsprotokoll kontrollieren.</p>`)}${card('Zeitpunkt wiederherstellen',recoveryForm(s,'cloud')+`<p class="muted">Geplante Dauer: 5 Simulationsminuten. Backupablage und aktueller Zielhost müssen verfügbar sein; das Ziel braucht freien Speicher. Ein Ausfall während des Zeitfortschritts bricht ohne Datenänderung ab; nach Reparatur neu starten. Eine zweite laufende Wiederherstellung wird nicht still ersetzt. Punktalter ist ein möglicher Datenrückstand, kein Beweis eines konkreten Verlusts. Ausfallbeginn und Zeitvorgaben können in der Vorschau angegeben werden. Die Wiederherstellung ist ein Provider-/Backupvorgang, kein Benutzer-Netztest. Originaldaten bleiben bei alternativem Ziel erhalten.</p>${recoveryStatus(b.restore,s.computed.recovery_timing?.cloud)}`)}</div>`+card('Wiederherstellungspunkte & Protokoll',table(['Zeit','Ergebnis','Details'],b.jobs.map(j=>['Minute '+j.minute,e(j.status),e(j.reason)])));}
case 'monitor':{let m=s.computed.active_metrics;return card('Azure Monitor · Auftragsanwendung',`<p>Aktuelles Auftrags-DNS-Ziel: <strong>${e(s.computed.active_target||'Nicht auflösbar')}</strong> · ${e(m.reason||'')}</p><div class="metrics">${[['CPU',metricDisplay(m,'cpu',' %')],['Speicher',metricDisplay(m,'memory',' %')],['Antwortzeit',metricDisplay(m,'response_ms',' ms')],['Fehlerrate (Modell)',metricDisplay(m,'error_rate',' %')]].map(([k,v])=>`<div><div class="eyebrow">${k}</div><div class="mini">${v}</div></div>`).join('')}</div><br>${metricControls(s.metrics)}<div class="spark" role="img" aria-label="CPU-Verlauf mit Quellen und Messlücken, höchstens 120 Punkte">${metricChart(s.metrics)}</div><small>Dienst-/Kapazitätsmodell, keine echte Hosttelemetrie. Neue Punkte tragen ihre damalige Quelle; ein dunkler Rand markiert Quellenwechsel, gestrichelte Markierung eine Messlücke. Graue historische Werte haben keine belegte Quelle und werden nicht dem heutigen DNS-Ziel zugeschrieben. 100 Prozent Modellfehler bezeichnet Dienstausfall, keine gemessene HTTP-Stichprobe. Netzpfad, Benutzeranmeldung und Datenzugriff separat prüfen.</small>`)+`<div class="grid two">${card('Last & Alarmregel',form('load',input('Lastpunkte','value',s.workload,'number'),'Last ändern')+alarmForm(s)+'<p class="muted">Das Fenster zählt aufeinanderfolgende Simulationsminuten ab einschließlich Schwelle; ein Wert darunter setzt die Folge zurück. Pro Regel wird der erste Metrikalarm erfasst. Auflösung, Quittierung und erneute Episoden sind nicht nachgebildet. Zeit läuft nur beim ausdrücklichen Vorspulen. Budgetwarnungen sind getrennte Ereignisse.</p>')}${card('Ausgelöste Alarme',table(['Minute','Typ / Kennung','Meldung / Nachweis'],s.alerts.map(a=>[a.minute,e(({metric:'Metrikalarm',budget:'Budgetwarnung',legacy:'Historischer Hinweis · Typ unbekannt'})[a.kind]||'Historischer Hinweis · Typ unbekannt')+'<br>'+e(a.rule),e(a.message)+'<br>'+alertEvidence(a)]))+table(['Regel / Ziel','Schwelle','Fenster','Aktuelle Folge / Messung'],s.alarms.map(a=>[e(a.id)+' / '+e(a.target),e(metricLabel(a.metric))+' ≥ '+a.threshold,a.window,a.streak+'<br>'+e(s.computed.alarm_metrics?.[a.target]?.reason||'')])))}</div>`+signinPanel()+historyPanel(s)+card('Metriken als Tabelle',metricTable(s.metrics));}
case 'costs':return `<div class="notice warn">Alle Werte sind fiktive Lernpreise, keine Azure-Angebote. Ist-Kosten betreffen vergangene Simulationszeit; Prognose = aktueller Stundensatz × ${s.tariffs.month_hours} Stunden (${e(s.tariffs.label)}). Budgetwarnungen schalten nichts ab.</div><div class="grid">${card('Bisher entstanden',`<div class="stat">${eur(s.cost)}</div><small>${s.minute} Simulationsminuten</small>`)}${card('Monatsprognose',`<div class="stat">${eur(s.computed.monthly)}</div><small>Aktuelle Konfiguration fortgeschrieben</small>`)}${card('Budget',form('budget',input('Warnbudget in Lern-Euro','value',s.budget,'number','step="0.01"'),'Budget setzen'))}</div><br>`+card('Tarife & Rechenweg',`<p>${e(s.computed.prices)}</p>`+table(['Ressource / Abteilung','Compute/h','Disk/h','Storage/h','Traffic/h','Dienst/h','Gesamt/h'],s.computed.hourly.map(x=>[e(x.resource)+' / '+e(x.department),...['compute','disk','storage','traffic','service','total'].map(k=>Number(x[k]).toFixed(5)+' Lern-Euro')]))+`<p class="muted">Vergangene Kosten bleiben bei späteren Konfigurations- oder Tagänderungen erhalten.</p>`)+card('Ist-Kosten nach Ressource und Abteilungs-Tag',table(['Ressource','Abteilung zum Verbrauchszeitpunkt','Kosten'],s.cost_ledger.map(x=>[e(x.resource),e(x.department),eur(x.amount)])));
case 'policy':return `<div class="notice">Region, Identität, Datennutzung, Aufbewahrung und technische Schutzmaßnahmen sind getrennte Prüfpunkte. Die Simulation erteilt keine Datenschutz-Zertifizierung.</div><div class="grid two">${card('Azure Policy (vereinfachte Lernregeln)',form('policy',select('Erlaubte Regionen','regions',[[JSON.stringify(s.policy.regions),'Aktuell: '+s.policy.regions.join(', ')],[JSON.stringify(['germanywestcentral','westeurope']),'Germany West Central + West Europe'],[JSON.stringify(['germanywestcentral']),'Nur Germany West Central'],[JSON.stringify(['westeurope']),'Nur West Europe']],JSON.stringify(s.policy.regions))+select('Verpflichtende Abteilungs-/Owner-Tags','require_tags',[['true','Ja'],['false','Nein']],s.policy.require_tags)+select('Neue öffentliche Endpunkte verweigern','deny_public',[['true','Ja'],['false','Nein']],s.policy.deny_public))+`<p class="muted">Änderungen an Ressourcen werden geprüft. Bereits vorhandene Verstöße werden sichtbar und müssen gesondert behoben werden.</p>`)}${card('Aktuelle Befunde',checks(Object.entries(r).map(([k,v])=>({label:k+': Region, Tags, öffentlicher Endpunkt',passed:s.policy.regions.includes(v.region)&&(!s.policy.require_tags||!!(v.owner.trim()&&v.department.trim()))&&(!s.policy.deny_public||!(v.public||v.public_ip))})))+checks([{label:'Vertrauliche Dateien nicht öffentlich lesbar',passed:!r.storage.public},{label:'Gastpartner ohne Personalzugriff',passed:!s.roles.some(x=>x.principal==='partner'&&['storage','subscription','rg-data','hr'].includes(x.scope))}]))}</div>`+card('Datenklassen & Aufbewahrung',table(['Klasse','Beispiel','Maßnahme'],[['öffentlich','Firmeninfo','Freigabe bewusst prüfen'],['intern','Betriebsanleitung','Nur Beschäftigte'],['vertraulich','Angebot-A','Vertriebsgruppe, minimale Rechte'],['besonders schutzbedürftig','Personal-B (rein fiktiv)','Personalbereich; begrenzte Aufbewahrung']])+decisionForm());
case 'cleanup':return businessPage();
case 'migration':return migrationPanel();
case 'notes':return card('Persönliche Arbeitsnotiz',form('notes',input('Anzeigename / Pseudonym','name',s.name)+field('Beobachtung → Vermutung → Änderung → Nachweis','text',s.notes),'Notiz speichern'))+card('Spielstand mitnehmen',`<p>Exportierte JSON-Dateien können über OneDrive verteilt werden. OneDrive ist kein Hosting; die Anwendung wird heruntergeladen, lokal entpackt und gestartet.</p><div class="actions">${cmd('Alle Übungen exportieren','bundle_export')}${cmd('Nur aktive Übung exportieren','export')}${cmd('Zusammenfassung exportieren','summary')}</div><p class="muted">Der Gesamtspielstand enthält alle bereits geöffneten Übungen einschließlich Notizen und Historien. Einzelne Übungen lassen sich weiterhin gesondert exportieren. Ein Lernstandsbericht dient der Besprechung und ist keine Sicherung.</p>`);
case 'trainer':return trainer();
}return '';}
function ticketDialogue(t){const s=record.state,messages=s.events.filter(x=>x.kind==='ticket_message'&&x.detail?.task===s.task).map(x=>({...x.detail,minute:x.minute}));const pending=messages.filter(x=>x.direction==='question'&&!messages.some(y=>y.reply_to===x.id));return card('Rückfragen zu diesem Auftrag',`<p>Vorbereitete Fragen erhalten die im Auftrag hinterlegte Antwort. Freie Fragen beantwortet die Lehrkraft.</p><div class="actions">${(t.clarifications||[]).map(q=>cmd(q.question,'ticket_ask',{topic:q.id})).join('')}</div><br>${form('ticket_ask',field('Eigene Rückfrage an die Firma','text',''),'Rückfrage speichern')}`+table(['Minute','Absender','Nachricht'],messages.map(x=>[x.minute,e(x.author)+(x.direction==='answer'?'<br><small>Antwort</small>':'<br><small>Rückfrage</small>'),(x.reply_to?'<small>Antwort auf: '+e(messages.find(q=>q.id===x.reply_to)?.text||'Frühere Frage')+'</small><br>':'')+e(x.text).replace(/\n/g,'<br>')]))+(record.role==='trainer'&&pending.length?form('ticket_answer',select('Offene Rückfrage','question',pending.map(x=>[x.id,x.author+': '+x.text]),pending[0].id)+field('Antwort als Lehrkraft im Auftrag der Firma','text',''),'Antwort speichern'):'')+`<p class="muted">Der Verlauf gehört zur aktiven Übung und Instanz und wird mit ihr gespeichert/exportiert. Wie das Ereignisprotokoll umfasst er die letzten 500 Modellereignisse; ältere Einträge können herausfallen. Freitext wird nicht automatisch fachlich bewertet.</p>`);}
function signinPanel(){const s=record.state,rows=s.events.filter(x=>x.kind==='signin'&&x.detail).slice().reverse();return card('Simulierte Anmeldeereignisse',form('signin',select('Lernidentität','user',Object.entries(s.users).map(([id,u])=>[id,id+' · '+u.name]),'lea')+select('Standort für die Prüfung','source',[['hq','Hauptstandort'],['branch','Außenstelle'],['home','Homeoffice']],'hq')+select('MFA-Nachweis im Lernmodell','mfa',[['true','Vorhanden'],['false','Fehlt']],'true'),'Anmeldung prüfen')+table(['Minute','Benutzer / Ziel','Standort / MFA','Identitätsprüfung','Anschließender Zugriff'],rows.map(x=>[x.minute,e(x.detail.user)+'<br>'+e(x.detail.target),e(x.detail.source)+' / '+(x.detail.mfa?'vorhanden':'fehlt'),status(x.detail.authenticated)+'<br>'+e(x.detail.reason),x.detail.access==='not_checked'?'Nicht geprüft':status(x.detail.access==='allowed')]))+`<p class="muted">Lernanmeldungen ohne echte Kennwörter oder Entra-Aufruf. Explizite Prüfung, Zugriffdiagnose und Öffnen der beiden Lernanwendungen erzeugen Einträge. Anmeldung und Daten-/Netzzugriff sind getrennt: eine erfolgreiche Anmeldung verleiht keine Zugriffsrechte. Reine Ansichts-/Bewertungsabfragen erzeugen keine Ereignisse. Verweigerte Schreibaktionen bleiben atomar; ihren Anmeldefehler können Sie hier separat prüfen. Die letzten 500 Modellereignisse werden gespeichert.</p>`);}

function recoveryStatus(job,timing){if(!job)return '';const t=timing||{status:job.status,planned_minutes:job.duration||5,reason:job.failure_reason||job.reason||''};const value=x=>x===null||x===undefined?'Nicht erfasst':x+' min';return card('Wiederherstellungsablauf',`<p>Status: <strong>${e(t.status)}</strong> · ${e(t.reason||'')}</p>`+table(['Ereignis / Ziel','Beobachtung'],[['Geplante Jobdauer',value(t.planned_minutes)],['Punktalter beim Start',value(t.point_age_at_start)],['Jobbeginn',t.started_minute==null?'Nicht erfasst':'Minute '+t.started_minute],['Erfasster Abschluss / Abbruch',t.finished_minute==null?'Nicht erfasst':'Minute '+t.finished_minute],['Dauer dieses Versuchs',value(t.attempt_minutes)],['Angegebener Ausfallbeginn',t.outage_minute==null?'Nicht angegeben':'Minute '+t.outage_minute],['Seit angegebenem Ausfall bis Nachweis / jetzt',value(t.elapsed_since_outage)],['RPO-Abstand zum angegebenen Ausfall',value(t.rpo_minutes)],['RPO-Vorgabe',value(t.rpo_limit)],['Zeit bis erfolgreichem Zielbestand',t.recovery_minutes==null?'Noch nicht nachgewiesen':value(t.recovery_minutes)],['RTO-Vorgabe für diesen Zielbestand',value(t.rto_limit)],['RTO-Vorgabe erfüllt',t.rto_within_limit==null?'Nicht beurteilbar':t.rto_within_limit?'Ja':'Nein']])+`<p class="muted">RPO: maximal tolerierter Datenrückstand. RTO: maximal tolerierte Wiederherstellungszeit. Punktalter und konkrete Änderungen sind verschiedene Informationen. Ein Fehler erreicht das Ziel nicht; Reparatur allein startet keinen neuen Versuch. Ohne erfassten Ausfallbeginn/Abschluss wird keine erreichte RTO behauptet. Eine alternative Datei muss noch fachlich geprüft bzw. eingebunden werden; sie stellt nicht automatisch den gesamten Geschäftsdienst wieder her.</p>`);}
function metricDisplay(m,key,suffix=''){return ((m.available===false&&key!=='error_rate')||(key==='error_rate'&&m.supported===false))?'—':e(m[key])+suffix;}
function metricRows(rows){return rows.filter(x=>metricSource==='all'||(metricSource==='legacy'?!('target'in x):'target:'+x.target===metricSource));}
function metricControls(rows){const values=[['all','Alle aufgezeichneten Quellen'],...Array.from(new Set(rows.filter(x=>'target'in x).map(x=>x.target))).map(t=>['target:'+t,t||'Kein auflösbares Ziel']),...(rows.some(x=>!('target'in x))?[['legacy','Historisch · Quelle unbekannt']]:[])];if(!values.some(([v])=>v===metricSource))metricSource='all';return '<label>Quelle im Verlauf<select data-metric-source>'+options(values,metricSource)+'</select></label>';}
function metricChart(rows){let previous;return metricRows(rows).map(x=>{const known='target'in x,gap=known&&!x.available,source=known?(x.target||'Kein auflösbares Ziel'):'Historisch · Quelle unbekannt',label='Minute '+x.minute+' · '+source+' · '+(gap?'Messlücke: '+x.reason:'CPU '+x.cpu+'%'),switched=previous!==undefined&&previous!==source;previous=source;return '<span '+(gap?'data-metric-gap ':'')+'style="height:'+(gap?8:Math.max(2,Math.min(100,Number(x.cpu)||0)))+'%;background:'+(gap?'transparent':known?'#6b94ee':'#8b939f')+';'+(gap?'border-bottom:2px dashed #8b939f;':'')+(switched?'border-left:2px solid #172b4d;':'')+'" title="'+e(label)+'" aria-label="'+e(label)+'"></span>';}).join('')||'Keine Werte für diese Auswahl.';}
function metricTable(rows){return table(['Minute','Quelle','Modellmessung / Grund','CPU %','RAM %','Antwort ms','Fehler %'],metricRows(rows).map(x=>[x.minute,e('target'in x?(x.target||'Kein auflösbares Ziel'):'Historisch · Quelle unbekannt'),e('available'in x?(x.available?'Verfügbar':x.reason):'Historischer Wert; Quelle/Verfügbarkeit nicht belegt'),metricDisplay(x,'cpu'),metricDisplay(x,'memory'),metricDisplay(x,'response_ms'),e(x.error_rate)]));}
function alertEvidence(a){const d=a.detail||{};if(a.kind==='metric')return e(d.target)+' · '+e(d.metric)+' ≥ '+e(d.threshold)+' · '+e(d.window)+' aufeinanderfolgende Minuten ('+e(d.start_minute)+'–'+e(d.end_minute)+') · letzter Wert '+e(d.value)+' · Ziel '+e(d.destination);if(a.kind==='budget')return 'Lernbudget '+e(d.threshold)+'% · '+eur(d.cost)+' von '+eur(d.budget)+' · kein automatisches Abschalten';return 'Kein belegter Metriktyp; bei Bedarf einen neuen gezielten Lasttest ausführen.';}
function recoveryInputs(s,area){const draft=recoveryDraft?.area===area?recoveryDraft:{};return '<p class="wide muted">RPO (Recovery Point Objective) ist der maximal tolerierte Datenrückstand als Zeitspanne. RTO (Recovery Time Objective) ist die maximal tolerierte Zeit bis zum festgelegten Wiederanlauf. Hier vergleichst du den gewählten Zielbestand; eine Datei allein stellt nicht die gesamte Anwendung wieder her. Fünf Minuten sind die geplante Jobdauer. Die optionalen Angaben ändern keine festgelegte Aufgabenfrist.</p>'+input('Simulierte IT-Identität','actor',draft.actor||'it')+input('Bekannter Ausfallbeginn (Simulationsminute, sonst leer)','outage_minute',draft.outage_minute??'','number',`min="0" max="${s.minute}"`)+input('RPO-Vorgabe für den Zielbestand (Minuten, optional)','rpo_limit',draft.rpo_limit??'','number','min="0" max="43200"')+input('RTO-Vorgabe für den Zielbestand (Minuten, optional)','rto_limit',draft.rto_limit??'','number','min="0" max="43200"');}
function recoveryForm(s,area){const b=area==='cloud'?s.backup:s.onprem.backup,draft=recoveryDraft?.area===area?recoveryDraft:{},keys=[...new Set([...(area==='cloud'?Object.keys(s.documents):Object.keys(s.onprem.documents)),...b.points.flatMap(p=>Object.keys(p.documents))])];return form(area==='cloud'?'restore':'local_restore',select('Vorhandener Wiederherstellungspunkt','point',b.points.map(p=>[p.id,'Minute '+p.minute+' · '+p.id]),draft.point||b.points[0]?.id)+(area==='local'?select('Umfang','scope',[['file','Einzeldatei'],['application','Lokalen Datei-/Auftragsbestand ersetzen']],draft.scope||'file'):'')+select('Dokument (nur bei Einzeldatei)','id',keys,draft.id||(area==='cloud'?'offer':'angebot-lokal'))+input('Dateiziel (nur bei Einzeldatei, alternativ empfohlen)','target',draft.target||(area==='cloud'?'offer-restored':'angebot-lokal-restored'))+recoveryInputs(s,area),'Auswirkungen prüfen · noch nichts wiederherstellen');}
function restorePreviewHtml(r){const text=row=>row===null?'Nicht vorhanden':JSON.stringify(row,null,2),kind=k=>k==='document'?'Beleg':'Auftrag',detail=(row,left,right)=>`<details><summary>${e(kind(row.kind)+' '+row.id)}</summary><div class="grid two">${card('Aktuell',`<pre class="code">${e(text(left))}</pre>`)}${card('Punktfassung / erwarteter Zielbestand',`<pre class="code">${e(text(right))}</pre>`)}</div></details>`;return card('Wiederherstellungsvorschau · noch keine Änderung',`<p>Stand Revision ${r.revision} · Momentaufnahme Minute ${r.snapshot_minute}. Gewählter Punkt: <strong>${e(r.point)}</strong> aus Minute ${r.point_minute}; Alter ${r.point_age_minutes} min.</p><p>Bereich ${e(r.area==='cloud'?'Cloud':'Lokal')} · ${e(r.scope==='application'?'Gesamter lokaler Datei-/Auftragsbestand':r.source+' → '+r.target)}</p><p>${e(r.preservation)}</p><p>${e(r.assumptions)}</p>`+table(['Zeit / Vorgabe','Vorschau'],[['Erwarteter Abschluss bei unverändertem Zustand',r.expected_finish_minute==null?'Nach Reparatur neu prüfen':'Minute '+r.expected_finish_minute],['RPO-Abstand zum angegebenen Ausfall',r.rpo_minutes==null?'Ausfallbeginn nicht angegeben':r.rpo_minutes+' min'],['Angegebene RPO-Vorgabe',r.rpo_limit==null?'Nicht angegeben':r.rpo_limit+' min'],['RPO-Vorgabe erfüllt',r.rpo_within_limit==null?'Nicht beurteilbar':r.rpo_within_limit?'Ja':'Nein'],['Prognose bis Zielbestand ab angegebenem Ausfall',r.projected_recovery_minutes==null?'Ausfallbeginn nicht angegeben':r.projected_recovery_minutes+' min'],['Angegebene RTO-Vorgabe',r.rto_limit==null?'Nicht angegeben':r.rto_limit+' min'],['RTO-Vorgabe voraussichtlich erfüllt',r.projected_rto_within_limit==null?'Nicht beurteilbar':r.projected_rto_within_limit?'Ja':'Nein']])+(r.point_after_outage?'<p class="notice warn">Der Punkt liegt nach dem angegebenen Ausfall. Prüfe seine Inhalte; jung bedeutet nicht automatisch fachlich richtig.</p>':'')+`<h3>Unterschiede seit diesem Punkt (${r.changes.length})</h3><p>Ein Zeitabstand allein beweist keinen Nutzdatenverlust. Diese Liste vergleicht tatsächliche Datensätze; die gewählte Wiederherstellung betrifft nur die unten genannten Ziele.</p>`+(r.changes.length?r.changes.map(row=>detail(row,row.current,row.point)).join(''):'<p>Keine Unterschiede in den vom Punkt erfassten Daten.</p>')+`<h3>Auswirkungen der gewählten Wiederherstellung (${r.effects.length})</h3>`+r.effects.map(row=>`<p>${e(row.effect==='remove_from_active_store'?'Wird aus dem aktiven Bestand entfernt; vorheriger Stand bleibt im Rückfallpunkt.':row.effect==='create_copy_keep_original'?'Neue Kopie, Original unverändert.':row.effect==='replace_active_preserve_history'?'Punktfassung wird aktuell; neuere Fassung bleibt als Version.':'Aktiver Bestand wird auf die Punktfassung gesetzt.')}</p>`+detail(row,row.current,row.expected)).join('')+`<p>${e(r.not_covered.join(' '))}</p>`+(r.can_start?`<button type="button" class="primary" data-restore-start="${e(JSON.stringify({action:r.action,parameters:r.parameters,instance:r.instance,revision:r.revision}))}">Diese Wiederherstellung starten</button>`:`<p class="notice warn">Start derzeit verweigert: ${e(r.blocked_reason)}</p>`));}
function localPage(){const s=record.state,p=s.onprem;const migration=s.local_migration,cloudActive=migration?.active;const ordersView=cloudActive?Object.fromEntries(Object.entries(s.orders).filter(([id])=>migration.owned_orders.includes(id))):p.orders;if(!p?.enabled)return card('Lokale Firmeninfrastruktur',`<p>Dieser ältere Spielstand erhält keine zusätzlichen lokalen Geschäftsdaten ohne bewusste Einrichtung. Die bestehenden Cloud-Daten bleiben erhalten.</p>${cmd('Fiktiven lokalen Betriebsbereich einrichten','local_initialize',{},'primary')}`);const users=Object.keys(p.accounts).map(id=>[id,id+' · '+(s.users[id]?.name||'lokales Dienstkonto')]);const auth=()=>select('Als lokales Konto','user',users,'u11')+select('Quelle','source',[['hq','Hauptstandort / LAN'],['branch','Außenstelle / Firmennetz'],['cloud','Cloud über VPN'],['internet','Internet']],'hq');const fileOptions=Object.entries(p.documents).map(([id,d])=>[id,id+' · '+d.name]);const orderFileOptions=cloudActive?Object.entries(s.documents).filter(([id])=>migration.owned_documents.includes(id)).map(([id,d])=>[id,id+' · '+d.name]):fileOptions;const orderAuth=cloudActive?()=>select('Als Entra-Konto im Cloudbetrieb','user',Object.entries(s.users).map(([id,u])=>[id,id+' · '+u.name]),'u11')+select('Quelle','source',[['hq','Hauptstandort'],['branch','Außenstelle'],['cloud','Cloud'],['internet','Internet']],'hq'):auth;return (cloudActive?'<div class="notice warn">Programmeinstieg im Cloudbetrieb: Aufträge und Formularversionen stammen jetzt vom Cloudziel '+e(migration.target)+'. Anmeldung über Entra; alte Quelldateien sind eingefroren. Migration und Rückfall im Migration Center.</div>':'')+`<div class="notice">IT-Konsole der fiktiven lokalen Firma. Lokale AD-Konten, Gruppen und Freigaben sind von Entra und Azure-Rollen getrennt. Kein automatischer Verzeichnisabgleich, keine echten Server oder Passwörter. Lokaler Geschäftsbestand und Sicherung sind eigene Daten derselben Firma; ein Cloud-Umzug dieser Daten ist noch kein automatischer Teil des bisherigen ORDER-01-Migrationsprofils.</div>`+card('Lokaler Betrieb und tatsächlich wirksame Abhängigkeiten',table(['Dienst','Adresse / TCP','Zustand','Abhängigkeit'],Object.entries(p.services).map(([id,r])=>[e(id),e(s.computed.local_addresses[id])+' / '+r.port,e(r.status)+(r.configured?'':' · Konfiguration fehlt'),e({'AD-01':'LAN; lokale Anmeldung','FILE-01':'LAN und AD-Konto/Freigabe','ORDER-01':'AD, SQL-01, FILE-01, svc-orders','SQL-01':'LAN; Datenbankanwendungsgruppe','BACKUP-01':'AD, FILE-01, SQL-01, svc-backup'}[id])]))+`<p>LAN: ${status(p.lan)} · Cloud-VPN: ${status(s.network.vpn)} · Lokale App für u11: ${status(s.computed.local_application.allowed)}</p>${form('local_network',select('Lokales LAN','lan',[['true','Verfügbar'],['false','Unterbrochen']],p.lan),'LAN-Zustand speichern')}<p class="muted">LAN-Zugriff benötigt kein Cloud-VPN. Cloud-Zugriff benötigt VPN und die Freigabe jedes benötigten lokalen Dienstes. Kein öffentlicher lokaler Endpunkt; Dienstadressen folgen dem konfigurierten Firmennetz. Lokale Hardwarekosten werden nicht als Azure-Verbrauch berechnet.</p>`)+card('Lokale DNS-Zuordnung',Object.entries(p.dns).map(([host,target])=>cloudActive&&host==='auftrag.lan'?'<p><strong>auftrag.lan → '+e(target)+'</strong><br>Auftragsroute wird durch Migration umgeschaltet.</p>':form('local_dns',`<input type="hidden" name="host" value="${e(host)}"><strong>${e(host)}</strong>`+select('Zieldienst','target',Object.keys(p.services),target),'DNS-Ziel speichern')).join(''))+`<div class="grid two">${card('Lokale Dienste konfigurieren',Object.entries(p.services).map(([id,r])=>`<details><summary>${e(id)} · ${e(r.status)} / Port ${r.port}</summary>${form('local_service',`<input type="hidden" name="id" value="${e(id)}">`+select('Dienstzustand','status',[['running','Gestartet'],['stopped','Gestoppt']],r.status)+input('TCP-Dienstport','port',r.port,'number')+select('Konfiguration','configured',[['true','Vollständig'],['false','Fehlerhaft']],r.configured)+select('Cloud-Quellen erlauben','allow_cloud',[['false','Nein'],['true','Nur über VPN'] ],r.allow_cloud)+input('Modellierte Kapazität (GB)','capacity_gb',r.capacity_gb,'number')+input('Modelliert belegt (GB)','used_gb',r.used_gb,'number'),'Dienst speichern')}</details>`).join(''))}${card('Lokale AD-Konten und Gruppen',table(['Lokales Konto','Aktiv','Gruppen',''],Object.entries(p.accounts).map(([id,u])=>[e(id),status(u.active),e(Object.entries(p.groups).filter(([g,m])=>m.includes(id)).map(([g])=>g).join(', ')),cmd(u.active?'Deaktivieren':'Aktivieren','local_account',{id,changes:{active:!u.active}})]))+form('local_membership',select('Lokale Gruppe','group',Object.keys(p.groups),'Vertrieb')+select('Lokales Konto','member',users,'lea')+select('Mitgliedschaft','add',[['true','Hinzufügen'],['false','Entfernen']],'true'),'Lokale Mitgliedschaft speichern')+`<p class="muted">Die lokale IT-Konsolenberechtigung bleibt von der Verfügbarkeit des AD-Dienstes getrennt, damit ein Ausfall repariert werden kann. Sie ist eine Modellkonsole, kein realer Domänen-Admin-Login.</p>`)}</div><br>`+card('Lokale Dateien · IT-Bestandsansicht',table(['Kennung / Version','Datei / Klasse','Status'],Object.entries(p.documents).map(([id,d])=>[e(id)+' / '+d.version,e(d.name)+'<br>'+e(d.class),d.deleted?'Gelöscht':'Vorhanden']))+form('local_read',auth()+select('Datei','id',fileOptions,'angebot-lokal'),'Datei als Benutzer lesen')+form('local_write',auth()+select('Datei','id',fileOptions,'angebot-lokal')+field('Neuer fiktiver Dateiinhalt','content',''),'Datei mit neuer Version speichern')+form('local_delete',auth()+select('Datei','id',fileOptions,'angebot-lokal'),'Datei als Benutzer löschen')+`<p class="muted">Nur die Benutzerprüfung liefert Inhalt. Lokale Änderungen erzeugen echte Versionen; Löschen ist im Modell wiederherstellbar, keine physische Löschung. Modellierte GB-Belegung ist eine separate Lehrgröße, keine Byte-Messung des Textes.</p>`)+card('Lokale Freigabegruppen',Object.entries(p.shares).map(([share,acl])=>form('local_acl',`<input type="hidden" name="share" value="${e(share)}"><strong>${e(share)}</strong>`+input('Lesende Gruppen (kommagetrennt)','read',acl.read.join(','))+input('Schreibende Gruppen (kommagetrennt)','write',acl.write.join(',')),'Freigabegruppen speichern')).join(''))+card(cloudActive?'Auftragsanwendung · aktueller Cloudbestand':'Interne Auftragsanwendung · echter lokaler SQL-Bestand',form('local_open',orderAuth(),'Lokale Anwendung als Benutzer öffnen')+table(['Kennung / Version','Kunde','Betreff','Status','Dokument'],Object.entries(ordersView).map(([id,row])=>[e(id)+' / '+row.version,e(row.customer),e(row.subject),e(row.status),e(row.document)]))+`<details><summary>Neuen lokalen Auftrag erfassen</summary>${form('local_order_create',orderAuth()+input('Kennung','id','LP-1002')+input('Fiktiver Kunde','customer','Fiktiv: Beispiel GmbH')+input('Betreff','subject','Lokale Anfrage')+input('Betrag (fiktiv)','amount',1200,'number')+select('Status','status',['Neu','In Bearbeitung','Erledigt'],'Neu')+select('Datei','document',orderFileOptions,'angebot-lokal'),'Lokalen Auftrag speichern')}</details>`+Object.entries(ordersView).map(([id,row])=>`<details><summary>${e(id)} ändern</summary>${form('local_order_update',orderAuth()+`<input type="hidden" name="id" value="${e(id)}"><input type="hidden" name="version" value="${row.version}">`+input('Kunde','customer',row.customer)+input('Betreff','subject',row.subject)+input('Betrag (fiktiv)','amount',row.amount,'number')+select('Status','status',['Neu','In Bearbeitung','Erledigt'],row.status)+select('Datei','document',orderFileOptions,row.document),'Mit aktueller Version ändern')}</details>`).join('')+`<p class="muted">${cloudActive?'Die aktuellen Auftragsdaten liegen im Cloudbestand. Entra-Anmeldung, Cloud-Datenrollen, Zielnetzpfad und Cloud-Dienstidentität bestimmen den Zugriff. Direkte lokale Dateizugriffe oben bleiben ein separater AD-Pfad.':'SQL ist ein strukturierter lokaler Lernbestand, kein echter SQL-Server. svc-orders benötigt lokale Datei-/Datenbankgruppen. Azure-Rollen ändern diese lokalen Rechte nicht.'}</p>`)+card('Lokale Sicherung und Wiederherstellung',form('local_backup_config',input('Intervall (Minuten)','interval',p.backup.interval,'number')+input('Aufbewahrung (Minuten)','retention',p.backup.retention,'number')+select('Lokaler Plan','enabled',[['true','Aktiv'],['false','Inaktiv']],p.backup.enabled),'Lokalen Sicherungsplan speichern')+cmd('Lokale Dateien und Aufträge jetzt sichern','local_backup_run')+recoveryForm(s,'local')+recoveryStatus(p.backup.restore,s.computed.recovery_timing?.local)+table(['Minute','Ergebnis','Grund'],p.backup.jobs.map(j=>[j.minute,e(j.status),e(j.reason)]))+`<p class="muted">Gemeinsame Simulationsuhr; lokal fünf Minuten geplanter Restore. Vor Erfolg wird der bisherige lokale Gesamtbestand zusätzlich als Rückfallpunkt erhalten. Dateiversionen bleiben beim In-place-Dateirestore erhalten. Ein kompletter Anwendungsrestore ersetzt den lokalen Bestand bewusst durch den Punkt; er kopiert keine Daten in die Cloud. Maximal 100 lokale Punkte/Jobprotokolle plus eingestellte Altersgrenze; regelmäßige Gesamtspielstand-Exporte sichern längere Historien.</p>`);}

function ticketDiagnostics(t){const evidence=record.assessment.diagnostic_evidence;if(!Array.isArray(evidence))return '<p class="notice">Nachweisübersicht in dieser älteren Ansicht nicht vorhanden. Keine Aktualität aus fehlenden Angaben ableiten.</p>'+(t.probes.some(p=>p.when&&!Array.isArray(p.when))?'<p>Bedingte Prüfungen benötigen die aktuelle serverseitige Nachweisübersicht. Ansicht neu laden.</p>':'')+'<div class="actions">'+t.probes.filter(p=>!p.when||(Array.isArray(p.when)&&p.when.reduce((v,k)=>v?.[k],record.state)===true)).map(p=>cmd((TEST_LABELS[p.test]||p.test)+' · '+JSON.stringify(p.args),'diagnose',{test:p.test,args:p.args})).join('')+'</div>';if(!evidence.length)return '<p>Für diese Aufgabe sind keine verpflichtenden Direktprüfungen hinterlegt.</p>';return '<p>Der Server vergleicht den aktuellen Modellzustand mit dem Prüfziel. Das ist noch kein von dir ausgeführter Diagnoseversuch. Nach Änderungen passende erlaubte und verweigerte Prüfungen erneut ausführen.</p>'+table(['Prüfauftrag und Ziel','Aktueller Modellzustand','Gespeicherter passender Versuch','Aktion'],evidence.map(p=>{const saved=p.recorded;return ['<strong>'+e(p.description)+'</strong><br>Soll: '+(p.expected?'Erlaubt':'Verweigert')+'<details><summary>Auftragsparameter und aktuelle Standardwerte</summary><pre class="code">'+e(JSON.stringify(p.effective_args,null,2))+'</pre></details>',(p.current_allowed?'Erlaubt':'Verweigert')+'<br>'+'<span class="pill '+(p.current_passed?'good':'bad')+'">'+(p.current_passed?'Prüfziel erfüllt':'Prüfziel nicht erfüllt')+'</span>',saved?'Minute '+e(saved.minute)+' · Änderungsstand '+e(saved.seq)+(saved.test?'<br>Gespeicherter Prüfer: '+e(TEST_LABELS[saved.test]||saved.test):'')+'<br>'+(saved.allowed?'Damals erlaubt':'Damals verweigert')+'<br><strong>'+(p.fresh?'Vom Prüfer dem aktuellen Änderungsstand zugeordnet':'Veraltet · erneut prüfen')+'</strong><details><summary>Damals ausdrücklich gespeicherte Parameter</summary><pre class="code">'+e(JSON.stringify(saved.args,null,2))+'</pre></details>':'Noch kein passender gespeicherter Versuch',cmd('Prüfen: '+p.description,'diagnose',{test:p.test,args:p.args})];}))+'<p class="muted">Der Nachweisabgleich verwendet dieselben aktuellen Standardwerte wie der Aufgabenprüfer. Die gespeicherten Rohparameter bleiben erhalten; fehlende historische Angaben werden hier nicht als damals ausdrücklich gespeicherte Werte ergänzt. Eine aktuelle verweigerte Prüfung kann genau das geforderte Schutzziel erfüllen. Bei Rollenvergabe werden ältere access/assign- und neue Verwaltungsdiagnosen nach Identität, Ziel, Operation und MFA abgeglichen; eine Datei-Quelle bestimmt das Verwaltungsrecht nicht.</p>';}
function ticket(t){const s=record.state;return card(t.title,`<div class="row"><span class="pill">${e(t.sender)}</span><small>${t.minutes} min · Vorwissen: ${e(t.prerequisite)}</small></div><br>${(t.terms||[]).length?card('Begriffe für diesen Auftrag',table(['Begriff','Bedeutung'],t.terms.map(term=>[e(term.term),e(term.meaning)]))):''}<p>${e(t.message)}</p><p><strong>${e(t.learn)}</strong><br>${e(t.try_text)}</p><p><strong>Arbeitsweg im Portal</strong><br>${e(t.function)}</p><p class="muted">${e(t.deadline)}<br>${e(t.constraints)}<br>Anhang: ${e(t.attachment)}</p>${t.id!==s.task?`<p>Diese Aufgabe ist derzeit nicht aktiv.</p>${record.role==='trainer'?cmd('Aufgabe freigeben / gespeicherten Stand öffnen','select_task',{id:t.id},'primary'):'<p>Die Lehrkraft wählt die aktive Aufgabe.</p>'}`:`<div class="notice">${e(t.initial)} Status: ${e(s.task_status)}</div><div class="actions">${cmd('1 · Denkanstoß','hint',{level:0})}${cmd('2 · Diagnosehinweis','hint',{level:1})}${cmd('3 · Konkrete Hilfe','hint',{level:2})}</div><br>${t.id==='free'?'<p class="notice">Freie Umgebung ohne Pflichtkriterien oder Abschlussbewertung. Eigene Versuche und Beobachtungen sind freiwillig.</p>':card('Geforderte Nachweise',checks(record.assessment.checks))}<h3>Direkt prüfen · Ziel und Nachweise</h3>${ticketDiagnostics(t)}<br>${t.id==='intro'?card('Dein erster Arbeitsgang',`<ol><li>Lies den Bedarf und die Schutzbedingungen. Untersuche die betroffene Identität und Ressource und führe die passenden Prüfungen unten aus. Vergleiche Netzwerk, Anmeldung und wirksame Rollen.</li><li>Leite aus der Diagnose eine gezielte Änderung ab. Nutze bei Bedarf die drei Hilfestufen, bevor du die konkrete Lösung ansiehst.</li><li>Kehre zum Posteingang zurück. Nutze die frischen erlaubten und verweigerten Prüfungen, speichere deine begründete Rückmeldung und prüfe den Zustand.</li></ol><div class="actions"><button data-page="identity">Benutzer und Rechte untersuchen</button><button data-page="network">Netzpfad untersuchen</button></div><p class="muted">Der Ablauf hilft beim Einstieg. Andere fachlich gleichwertige Wege bleiben möglich; bewertet wird der tatsächliche Zustand.</p>`):''}${ticketDialogue(t)}${form('reply',field(t.id==='free'?'Eigene Beobachtung (freiwillig)':'Rückmeldung an die Firma: Was war die Ursache, was wurde geändert, was wurde geprüft?','text',s.replies[s.task]||''),t.id==='free'?'Beobachtung speichern':'Rückmeldung speichern')}<div class="actions">${t.id==='free'?'<button data-page="resources">Ressourcen frei untersuchen</button>':cmd('Lösung anhand des Zustands prüfen','check',{},'primary')}</div><p class="muted">Freitext wird gespeichert und vom Trainer besprochen. Der Simulator behauptet kein Sprachverständnis.</p>`}${record.role==='trainer'&&t.id!=='free'?`<details><summary>Trainerlösung & zulässige Alternativen</summary><p>${e(t.explanation)}</p><p>${e(t.alternatives)}</p>${cmd('Referenzlösung im Ausgangsstand ansehen','example_preview',{task:t.id})}${(t.variants||[]).map((item,index)=>`<p><strong>${e(item.label)}</strong> · ${e(item.rationale)}</p>${cmd('Zulässige Variante im Ausgangsstand ansehen','example_preview',{task:t.id,variant:index})}`).join('')}${(t.failures||[]).map((item,index)=>`<p><strong>Ungeeignet: ${e(item.label)}</strong> · ${e(item.rationale)}</p>${cmd('Fehlversuch im Ausgangsstand ansehen','example_preview',{task:t.id,failure:index})}`).join('')}</details>`:''}`);}
function availabilityResourceNotice(id){const a=record.state.computed.availability?.[id];return a?`<p class="notice">Laufzeit-/Standortmodell: ${e(a.online)}/${e(a.provisioned)} Instanzen verfügbar · Zonenbelegung ${e(a.placement.join(', '))}. ${e(a.reason)}<br><button data-page="availability">Verfügbarkeit und Abhängigkeiten untersuchen</button></p>`:'';}
function availabilityControl(){const s=record.state,x=s.availability_event;return record.role==='trainer'?card('Kontrollierter Lernzonenausfall',form('availability_event',select('Region','region',[...new Set(Object.values(s.resources).filter(r=>r.kind!=='SaaS').map(r=>r.region))],x.region)+select('Ausgefallene Lernzone','zone',[['1','Lernzone1'],['2','Lernzone2'],['3','Lernzone3']],x.zone)+select('Ereignis','enabled',[['true','Ausfall setzen'],['false','Ausfall beenden']],x.enabled),'Lernereignis anwenden')+'<p>Ändert keine Ressourcenkonfiguration und spult keine Zeit vor. Beenden stellt nur die Zone wieder bereit; Dienstfehler und andere Störungen bleiben. Danach Funktionen erneut prüfen.</p>'):'';}
function availabilityPage(){const s=record.state,x=s.availability_event;return card('Zonen und verbleibende Kapazität',`<p>${x.enabled?'Aktiver Ausfall: '+e(x.region)+' · Lernzone'+e(x.zone)+' seit Minute '+e(x.since):'Kein Lernzonenausfall aktiv.'}</p><p>Drei logische Lernzonen je Region. Ein Standort liegt im Modell in Zone1; verteilte Instanzen werden abwechselnd Zone1,2,3 zugeordnet. Eine einzelne Instanz bleibt genau eine Instanz. Ein Ressourceneintrag mit mehreren Instanzen fasst ein logisches Deployment zusammen, keine einzelne reale Azure-VM. Ein gemeinsamer Lern-Endpunkt ersetzt hier einen echten Load Balancer. Der Datenträgerwert ist ein vereinfachtes Gesamtbudget, kein Disk- oder Datenreplikationsmodell.</p><p>ZRS hält den logischen Storage-/Files-Bestand bei einem einzelnen Lernzonenausfall erreichbar. LRS/GRS haben hier ihren primären Standort in Zone1; es gibt keine automatische Regionsumschaltung. Lokales LAN/AD und externe SaaS-Anbieter sind unabhängig. Abschalten oder fehlende Daten-/Netzrechte werden durch Zonenverteilung nicht repariert.</p>`+table(['Ressource / Region','Verfügbar / vorgesehen','Zonenbelegung','Grund',''],Object.entries(s.computed.availability).map(([id,a])=>[e(id)+'<br>'+e(s.resources[id].region),e(a.online)+' / '+e(a.provisioned),e(a.placement.join(', ')),e(a.reason),`<button data-resource="${e(id)}">Konfiguration prüfen</button>`]))+`<p>Bei weniger verbleibenden Instanzen berechnen sich CPU/RAM/Antwortzeit und Modellfehler aus der Restkapazität. Vorgesehene Compute-/Plankapazität bleibt kostenpflichtig. Erst beim bewussten Vorspulen entstehen Kosten, Metrikhistorie, Alarme und Sicherungsläufe. ZRS und weitere Instanzen ersetzen keinen früheren Backup-Inhalt.</p><p class="muted">Keine echte Replikation, Warte-/Umschaltzeit, Regions-/SKU-Matrix, automatische VM-Neuanlage oder Azure-SLA. GRS-Failover und Replikationsverzögerung nicht simuliert. Alte Preisstände ohne ZRS-Preis bleiben unverändert; ZRS wird dort nicht als wählbare kostenfreie Option erfunden. Eine neue Übung mit passendem Tarif erlaubt die neue Auswahl.</p><button data-page="monitor">Restkapazität und Fehler prüfen</button> <button data-page="backup">Sicherung tatsächlich prüfen</button>`)+availabilityControl();}
function runtimeProfileNotice(id){const profile=record.state.computed.runtime_profiles?.[id];if(!profile||profile==='none')return '';return '<p class="notice">Laufzeitprofil: '+e({orders:'Aufträge · orders:1.0 / TCP443',requests:'Kundenanfragen · getrennte Anwendungsdaten und Konfiguration',shipping:'Versand · shipping:1.0 / TCP8080'}[profile]||profile)+'. '+(profile==='orders'?'Auch eigene VMs und App Services können denselben Firmen-Auftragsbestand über auftrag.intern bedienen. Image, Port, Konfigurationsstatus, Datenpfade, Dienstidentität und Benutzerrechte müssen passen. DNS-Umschaltung kopiert keine Daten; alte Laufzeiten können weiter Kosten erzeugen. Andere Images sind keine automatisch funktionierende Anwendung.':profile==='requests'?'Dieser Dienst gehört zu Kundenanfragen und ist keine Auftragslaufzeit; eine DNS-Änderung überträgt weder Daten noch Anwendungsrollen.':'Name/Wert-Konfiguration und tatsächliche Datenpfade separat prüfen.')+'</p>';}
function databaseForm(id,r){const t=record.state.tariffs;return form('database_resource',`<input type="hidden" name="id" value="${e(id)}"><p>Verwalteter Datenbank-Lernservice. Die Ressource db trägt den gemeinsamen strukturierten Firmen-Datenbestand; ihre Konfiguration und Erreichbarkeit wirken auf Aufträge, Kundenanfragen und Versand. Netzwerkzugang ist keine Datenfreigabe.</p>`+input('Anzeigename im Lernportal','name',r.name)+select('Region','region',['germanywestcentral','westeurope','eastus'],r.region)+input('Abteilung (Tag)','department',r.department)+input('Verantwortlich','owner',r.owner)+select('Reservierte Lernklasse (Preis; keine DB-Leistungsmessung)','size',Object.entries(t.sizes).map(([key,value])=>[key,key+' · '+eur(value.compute_hour)+'/h je Lerninstanz']),r.size)+input('Vorgesehene Lerninstanzen (Preis/Verfügbarkeit)','instances',r.instances,'number','min="1" max="10"')+select('Verteilung im Lernmodell','availability',[['single','Ein Standort (Zone1)'],['zones','Instanzen über Lernzonen1–3']],r.availability)+select('Subnetz des Lern-Endpunkts','subnet',Object.keys(record.state.network.subnets),r.subnet)+input('Private Lern-IP','ip',r.ip)+input('Öffentliche Lern-IP (leer = privat)','public_ip',r.public_ip)+input('TCP-Lernendpunktport','port',r.port,'number','min="1" max="65535"')+select('Datenbank-Konfiguration vollständig','configured',[['true','Ja'],['false','Nein']],r.configured)+select('Löschschutz','locked',[['false','Aus'],['true','Aktiv']],r.locked),'Datenbank-Lernservice konfigurieren')+'<p class="muted">Keine VM-OS-/Image-/Datenträger- oder Blob-Speicherklassenverwaltung. Kapazitätsklasse ändert den reservierten Lernpreis, nicht eine erfundene DB-CPU-/RAM-Messung. Instanzen ändern Preis und tatsächliche logische Restverfügbarkeit, keine echte Datenreplikation. Der DB-Port ist ein frei gewählter Lernendpunkt; direkte Tests verwenden den angegebenen Port. Die Firmen-Anwendungsprofile übernehmen den gespeicherten DB-Port im Modell automatisch; getrennte Client-Portkonfiguration und echter SQL-/TLS-Betrieb sind nicht modelliert.</p><p class="notice">Stoppen unterbricht den Datenbankdienst, behält aber reservierte Lernkosten. Eigene Preisannahme: echtes Azure Database for PostgreSQL beendet beim Stoppen die Compute-Abrechnung; sein Stop-/Speicher-/Neustartmodell wird hier nicht nachgebildet. Ein alter deallocated-Spielstand bleibt unverändert offline, bis der Dienst bewusst gestartet wird. Historische VM-/Storage-Felder bleiben erhalten, sind keine wirksamen DB-Einstellungen. Für db gibt es keine separate Datenbank-Kopie, Größen-/Performancezusage oder Azure-SKU-Nachbildung.</p>';}
const ACTION_LABELS={"configure":"Ressource konfigurieren","power":"Betriebszustand ändern","create":"Ressource anlegen","delete_resource":"Ressource entfernen","group_create":"Ressourcengruppe anlegen","network":"Netzwerk konfigurieren","subnet_set":"Subnetz konfigurieren","subnet_remove":"Subnetz entfernen","rule_add":"Netzwerkregel anlegen","rule_remove":"Netzwerkregel entfernen","user":"Benutzer konfigurieren","membership":"Gruppenmitgliedschaft ändern","role_add":"Rollenzuweisung hinzufügen","role_remove":"Eine Rollenzuweisung entfernen","file_write":"Datei mit neuer Version speichern","file_delete":"Datei löschen","version_restore":"Dateiversion wiederherstellen","request_deploy":"Kundenanfragen bereitstellen","request_select":"Anfrage-Laufzeit auswählen","request_config":"Anfrage-Laufzeit konfigurieren","request_grant":"Anfrage-Anwendungsrolle ändern","request_remove":"Anfrage-Bereitstellung entfernen","request_create":"Kundenanfrage anlegen","request_update":"Kundenanfrage ändern","request_open":"Kundenanfragen als Benutzer öffnen","storage_move":"Dokumentablage wechseln","data_policy":"Dokumentregel ändern","data_purge":"Dokumentinhalt bereinigen","backup_config":"Sicherungsplan konfigurieren","backup_run":"Sicherung ausführen","restore":"Wiederherstellung starten","advance":"Simulationszeit vorspulen","workload":"Modellierte Last ändern","alarm_add":"Alarmregel anlegen","budget":"Lernbudget ändern","policy":"Ressourcenrichtlinie ändern","decision":"Begründete Entscheidung speichern","migration_plan":"Migrationsstrategie planen","migration":"Cloud-Laufzeitumzug ausführen","fault":"Trainerstörung steuern","service_identity":"Dienstidentität konfigurieren","order_create":"Auftrag anlegen","order_update":"Auftrag ändern","application_open":"Auftragsanwendung als Benutzer öffnen","notes":"Arbeitsnotiz speichern","reply":"Rückmeldung speichern","diagnose":"Funktion diagnostizieren","local_initialize":"Lokalen Firmenbereich einrichten","local_service":"Lokalen Dienst konfigurieren","local_account":"Lokales Konto konfigurieren","local_membership":"Lokale Gruppenmitgliedschaft ändern","local_network":"Lokales Netzwerk konfigurieren","local_acl":"Lokale Freigaberechte ändern","local_open":"Lokale Anwendung öffnen","local_read":"Lokale Datei lesen","local_write":"Lokale Datei speichern","local_delete":"Lokale Datei löschen","local_order_create":"Lokalen Auftrag anlegen","local_order_update":"Lokalen Auftrag ändern","local_backup_run":"Lokale Sicherung ausführen","local_backup_config":"Lokalen Sicherungsplan konfigurieren","local_restore":"Lokale Wiederherstellung starten","local_migration":"Lokale Datenmigration ausführen","business_policy":"Gemeinsame Geschäftsregel ändern","business_purge":"Geschäftsdaten und bekannte Kopien bereinigen","local_lineage":"Lokale Datenherkunft bestätigen","availability_event":"Lernzonenausfall steuern","container_config":"Container-Name/Wert-Konfiguration ändern"};
const EVENT_LABELS={change:'Konfigurationsaktion',diagnostic:'Diagnoseversuch',signin:'Simulierte Anmeldung',ticket:'Auftrag bereitgestellt',ticket_message:'Nachricht im Ticket',assessment:'Lösungsprüfung',backup:'Sicherung',restore:'Wiederherstellung',local_backup:'Lokale Sicherung',local_restore:'Lokale Wiederherstellung',local_migration:'Lokale Datenmigration',application_read:'Anwendungszugriff',save_migration:'Speicherformat übernommen',business_purge:'Geschäftsdaten bereinigt',data_purge:'Dokumentinhalt bereinigt',lineage_review:'Datenherkunft geprüft'};
